head.script:
//
window.MathJax = {

startup: {
    typeset: false 
  },

loader: {
    // 🔥 MathJax의 모든 확장 패키지를 한 번에 불러옵니다
    load: ['[tex]/cancel', '[tex]/enclose', '[tex]/autoload'],
    timeout: 30000
  },

  tex: {
    inlineMath: [['$', '$'], ['\\(', '\\)']],
    displayMath: [['$$', '$$'], ['\\[', '\\]']],
    packages: { '[+]': ['cancel', 'enclose'] },
    tags: 'ams', // 수식 자동 번호 매기기 유지
    processEscapes: true
  },
  // [리사이징 설정] 기존에 90% 정도를 쓰셨다면 아래 scale 값을 조절하세요
svg: {
    scale: 0.95,        
    minScale: 0.5,      
    displayAlign: 'center',
    mtextInheritFont: false,
    mtextFont: "'Latin Modern Roman', 'RIDIBatang', serif",
    unknownFamily: "'Latin Modern Roman', 'RIDIBatang', serif",
    fontCache: 'local'        // SVG DOM 노드 폭증 방지를 위해 local 캐시 사용
  },
  options: {
    renderActions: {
      // 기존 스크립트 태그 방식(math/tex) 호환성 유지
      findScript: [10, doc => {
        for (const node of document.querySelectorAll('script[type^="math/tex"]')) {
          const display = !!node.type.match(/; *mode=display/);
          const math = new doc.options.MathItem(node.textContent, doc.inputJax[0], display);
          const text = document.createTextNode('');
          node.parentNode.replaceChild(text, node);
          math.start = {node: text, delim: '', n: 0};
          math.end = {node: text, delim: '', n: 0};
          doc.math.push(math);
        }
      }, '']
    }
  }
};
//

