  --bg-header: #161618;
  --bg-input: #202024;
  --bg-blockquote: #202024;
  --bg-code-inline: #2A2A30;
  --bg-overlay: rgba(0, 0, 0, 0.54);
  --text-primary: #ECEAE4;
  --text-secondary: #C8C5BE;
  --text-body: #8C8982;
  --text-tertiary: #8C8982;
  --text-muted: rgba(236, 234, 228, 0.52);
  --text-faint: rgba(236, 234, 228, 0.32);
  --code-text: #ECEAE4;
  --blockquote-color: #C8C5BE;
  --border-subtle: #242429;
  --border-default: #2E2E35;
  --border-medium: #3E3E47;
  --border-strong: #52525E;
  --border-solid: #2E2E35;
  --border-dashed: #52525E;
  --border-accent: #4C9AFF;
  --shadow-card: none;
  --shadow-elevated: 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 1px 5px 0 rgba(0, 0, 0, 0.12);
  --shadow-inset: none;
  --scrollbar-track: #161618;
  --scrollbar-thumb: #2E2E35;
  --link-color: #4C9AFF;
  --link-hover-color: #79B5FF;
  --label-bg: #202024;
  --label-text: #C8C5BE;
  --highlight-bg: rgba(207, 160, 85, 0.25);
  --wikilink-bg: rgba(76, 154, 255, 0.12);
  --wikilink-bg-hover: rgba(76, 154, 255, 0.22);
  --overleaf-bg: #4ca746;
  --callout-def: #9F7AEA;
  --callout-cor: #ED64A6;
  --callout-axiom: #F56565;
  --callout-ex: #ECC94B;
  --callout-prob: #48BB78;
  --c-default: 76, 154, 255;
  --c-info: 56, 189, 248;
  --c-tip: 45, 212, 191;
  --c-success: 52, 211, 153;
  --c-warning: 251, 191, 36;
  --c-danger: 248, 113, 113;
  --c-quote: 148, 163, 184;
  --iframe-scheme: dark;
  --iframe-bg: #141517;
  --iframe-filter: none;
}

