/* ==========================================================================
   2. CONTEMPO FLAT UNIFIED DESIGN SYSTEM (Single-Source Variable Architecture)
   Consolidates Custom Features + Contempo Flat Master Layer without duplicates.
   Theme switching operates 100% through :root & body.light-mode CSS variables.
   ========================================================================== */

@font-face {
  font-family: 'RIDIBatang';
  src: url('https://cdn.jsdelivr.net/gh/projectnoonnu/noonfonts_twelve@1.0/RIDIBatang.woff') format('woff');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* --- 2.1 Global Reset, Typography & Sharp Geometry --- */
*, *::before, *::after {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  text-shadow: none !important;
}

body::before, body::after, html::before, html::after,
.noise-overlay, .bg-photo, .bg-photo-container, .bg-photo-overlay {
  display: none !important;
  content: none !important;
  background: none !important;
}

html {
  background: var(--bg-body) !important;
  background-color: var(--bg-body) !important;
  background-image: none !important;
  background-attachment: fixed !important;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
}

body {
  background: var(--bg-body) !important;
  background-color: var(--bg-body) !important;
  background-image: none !important;
  background-attachment: fixed !important;
  color: var(--text-body) !important;
}

body, #comments, .floating-footnote-content, .post-body, .sidebar-container {
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, system-ui, Roboto, "Helvetica Neue", "Segoe UI", "Apple SD Gothic Neo", "Noto Sans KR", "Malgun Gothic", "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", sans-serif !important;
}

#modern-series-nav, #settings-fab, #settings-panel, #spotlight-search-modal, #toc-wrapper,
.Label a, .byline, .comment-header, .flat-button, .load-more-btn, .notice-badge,
.pill-button, .settings-close, .tag-pill, .toc-btn, div.code-toolbar > .toolbar {
  font-family: Pretendard, sans-serif !important;
  letter-spacing: -0.02em !important;
}

body.latex-font, body.latex-font .callout-content,
body.latex-font .callout-title-inner, body.latex-font .post-body, body.latex-font .post-title,
body.latex-font h1, body.latex-font h2, body.latex-font h3, body.latex-font h4, body.latex-font h5 {
  font-family: "Latin Modern Roman", "RIDIBatang", serif !important;
}
body.latex-font .post-body {
  line-height: 1.8 !important;
  font-size: 1.05em !important;
}
body.latex-font mjx-container {
  font-size: 1.04em !important;
}
body.latex-font mjx-container[display="true"] {
  font-size: 1.02em !important;
}
body.latex-font .Header h1, body.latex-font .Header h1 a {
  font-family: $(blog.title.font.family) !important;
}

::selection {
  background: var(--accent) !important;
  color: var(--text-on-accent) !important;
  text-shadow: none !important;
}
::-moz-selection {
  background: var(--accent) !important;
  color: var(--text-on-accent) !important;
  text-shadow: none !important;
}

body.preload-theme, body.preload-theme * {
  transition: none !important;
}

.comment-link, .flat-button, .jump-link, a, button {
  touch-action: manipulation;
}
.flat-button, .jump-link, .pill-button, .settings-close, .toc-btn {
  -webkit-user-select: none;
  user-select: none;
}
.latex-overleaf-btn, a[href*="#fn"], button {
  transition: transform .4s cubic-bezier(.175, .885, .32, 1.275), background-color .2s, border-color .2s, box-shadow .2s, color .2s !important;
}

@media (prefers-reduced-motion: reduce) {
  *, :after, :before {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
  html { scroll-behavior: auto; }
}

.page_body, .page_body .centered {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* Sharp Rectangular Geometry (border-radius: 0) */
.post-outer-container, .widget.FeaturedPost, .PopularPosts, .sidebar-container,
.sidebar-container .widget, .widget.Profile, #comments, .comments .comment-replies .comment-block,
.comments .comment-form, .b-notification, .dialog, .subscribe-popup, #custom-notice-board,
.notice-badge, #toc-wrapper, #toc-wrapper.folded, .toc-btn, #settings-panel, .settings-close,
.setting-group, .setting-item button, .setting-item .setting-group button, #settings-fab,
#settings-fab.floating-settings-fab, .callout,
.floating-footnote-content, .footnote-close-btn, .reference-tooltip, .ref-close-btn,
a[href*="#fn"]:not(.footnote-backref), a.obsidian-wikilink, .post-body .obsidian-highlight,
.post-body mark, .floating-footnote-content mark, .reference-tooltip mark, div.code-toolbar,
div.code-toolbar > .toolbar, div.code-toolbar > .toolbar .toolbar-item button,
.callout-content code, .post-body code:not([class*="language-"]), .post-body table,
.post-body blockquote, .post-body img, .medium-zoom-image--opened, .snippet-thumbnail,
.snippet-thumbnail img, .PopularPosts .item-thumbnail, .PopularPosts .item-thumbnail img,
.series-meta .badge, #modern-series-nav, .series-header, .series-dropdown, .nav-btn,
.load-more-btn, .flat-button, .pill-button, .jump-link, .comment-link, .Label li,
.Label span.label-size, .Label a, .byline.post-labels a, .tag-pill, .search-modal-content,
#spotlight-input, .search-shortcut-hint, .result-item, .skeleton-ui,
.post-skeleton-wrapper .skel-title, .post-skeleton-wrapper .skel-line,
.post-skeleton-wrapper .skel-box, #reading-progress-bar,
::-webkit-scrollbar-track, ::-webkit-scrollbar-thumb {
  border-radius: 0px !important;
}

/* Circular User Avatars & Spinners */
.avatar-image-container, .avatar-image-container img, .profile-img, .widget.Profile img, .lm-spinner {
  border-radius: 50% !important;
}

/* --- 2.2 MathJax & SVG Rendering --- */
.MathJax_Preview {
  display: none !important;
  color: transparent !important;
}
.MJX_Assistive_MathML, mjx-assistive-mml {
  display: none !important;
  position: absolute !important;
  top: -9999px !important;
  left: -9999px !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
}
span.math, span.math.display, span.math.inline {
  border: none !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  box-shadow: none !important;
  text-decoration: none !important;
}
.MathJax_Display, .MathJax_SVG_Display, mjx-container[display="true"], span.math.display, .post-body .katex-display {
  display: block !important;
  width: 100% !important;
  max-width: 100%;
  box-sizing: border-box;
  text-align: center !important;
  margin: 1.5em auto !important;
  padding: 10px 0;
  overflow-x: auto !important;
  overflow-y: hidden !important;
}
#comments svg, .MathJax_SVG, .MathJax_SVG_Display, .post-body svg {
  pointer-events: none !important;
  user-select: none !important;
  touch-action: pan-x pan-y !important;
  max-width: 100% !important;
  height: auto !important;
}
.post-body mjx-container:not([display="true"]) {
  max-width: 100% !important;
}
.MathJax_SVG {
  margin: 0 2px !important;
}
.MathJax_SVG, mjx-container {
  color: inherit !important;
}
mjx-container {
  display: inline-block !important;
  margin: 0 .1em !important;
}
mjx-container svg text,
body > svg > text,
svg text[data-variant] {
  font-family: "Latin Modern Roman", "RIDIBatang", serif !important;
  letter-spacing: normal !important;
  word-spacing: normal !important;
  stroke: none !important;
  stroke-width: 0 !important;
  inline-size: auto !important;
}
.section-toggle-icon svg {
  vertical-align: middle !important;
}
.callout-title-inner mjx-container[display="true"] {
  margin: 0 4px !important;
}
.callout mjx-container, .callout mjx-container svg {
  flex-shrink: 0 !important;
}
#toc-wrapper .toc-body a .MathJax_SVG, #toc-wrapper .toc-body a mjx-container,
.PopularPosts a .MathJax_SVG, .PopularPosts a mjx-container,
.post-title .MathJax_SVG, .post-title a .MathJax_SVG, .post-title a mjx-container, .post-title mjx-container,
.sidebar-container .widget a .MathJax_SVG, .sidebar-container .widget a mjx-container {
  color: inherit !important;
}
#toc-wrapper .toc-body a .MathJax_SVG *, #toc-wrapper .toc-body a .MathJax_SVG [fill="currentColor"],
#toc-wrapper .toc-body a mjx-container svg, #toc-wrapper .toc-body a mjx-container svg [fill="currentColor"],
.PopularPosts a .MathJax_SVG *, .PopularPosts a .MathJax_SVG [fill="currentColor"],
.PopularPosts a mjx-container svg, .PopularPosts a mjx-container svg [fill="currentColor"],
.post-title .MathJax_SVG *, .post-title .MathJax_SVG [fill="currentColor"],
.post-title mjx-container svg, .post-title mjx-container svg [fill="currentColor"],
.sidebar-container .widget a .MathJax_SVG *, .sidebar-container .widget a .MathJax_SVG [fill="currentColor"],
.sidebar-container .widget a mjx-container svg, .sidebar-container .widget a mjx-container svg [fill="currentColor"] {
  fill: currentColor !important;
  stroke: currentColor !important;
}
.MathJax_SVG a, .MathJax_SVG a *, mjx-container a, mjx-container a * {
  fill: var(--accent) !important;
  stroke: var(--accent) !important;
  color: var(--accent) !important;
  text-decoration: none !important;
}

/* --- 2.3 Header, Sticky Navigation & Reading Progress Bar (Unified Flexbox Bar) --- */
.page_body .centered {
  padding-top: 8px !important;
}

.Header, .blog-name, .centered-top-container, .centered-top-placeholder, .header-inner, .header-widget {
  background: var(--bg-header) !important;
  background-color: var(--bg-header) !important;
  background-image: none !important;
  box-shadow: none !important;
}

/* Top Bar Outer Container (Clean Borderless Default, Bottom Hairline Only When Sticky) */
.centered-top-container,
.centered-top-placeholder {
  width: 100% !important;
  height: 56px !important;
  min-height: 56px !important;
  padding: 0 !important;
  margin: 0 0 16px 0 !important;
  border: none !important;
  border-bottom: none !important;
  box-sizing: border-box !important;
}

.centered-top-container.sticky {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border-bottom: 1px solid var(--border-subtle) !important;
  z-index: 50 !important;
  will-change: transform, opacity;
}

/* Desktop Sidebar & Right Docked ToC Offsets for Sticky Header */
@media screen and (min-width: $(sidebar.width + content.width + content.margin * 2)) {
  body:not(.zen-mode) .centered-top-container.sticky,
  body.collapsed-header:not(.zen-mode) .page_body .centered-top-container {
    left: $(sidebar.width) !important;
    padding-left: 0 !important;
    width: auto !important;
  }
}
@media screen and (min-width: 1360px) {
  body.item-view:not(.zen-mode):not(.toc-folded) .centered-top-container.sticky {
    right: 280px !important;
  }
}

body.ghost-ui-active .centered-top-container.sticky {
  transform: translateY(-100%) !important;
  transition: transform .3s cubic-bezier(.4, 0, .2, 1) !important;
}

/* Inner Flex Row (.centered-top): Matches .centered-bottom Width & Padding Exactly */
.centered-top,
.centered-top-container .centered-top,
.centered-top-container.sticky .centered-top {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 10px !important;
  width: 100% !important;
  max-width: $(content.width) !important;
  height: 56px !important;
  min-height: 56px !important;
  margin: 0 auto !important;
  padding: 0 28px !important;
  box-sizing: border-box !important;
  position: relative !important;
}
body.item-view .centered-top,
body.item-view .centered-top-container .centered-top,
body.item-view .centered-top-container.sticky .centered-top {
  max-width: 860px !important;
}
@media screen and (min-width: 1200px) {
  body.zen-mode.item-view .centered-top,
  body.zen-mode.item-view .centered-top-container.sticky .centered-top {
    max-width: 1050px !important;
  }
}
@media screen and (max-width: 800px) {
  .centered-top,
  .centered-top-container .centered-top,
  .centered-top-container.sticky .centered-top,
  body.item-view .centered-top,
  body.item-view .centered-top-container.sticky .centered-top {
    padding: 0 20px !important;
  }
}

/* Hide Legacy Clearboth, Unused Description, Top Nav & Native Search Form */
.centered-top .clearboth,
.blog-name .Header p,
.blog-name nav,
.blog-name .PageList,
.blog-name .subscribe-section-container,
#search_top {
  display: none !important;
}

/* [Slot 1: Left Action Button] Hamburger Menu (Home) & Return Link (Post) */
.centered-top > .hamburger-menu,
.centered-top > .return_link,
body.item-view .centered-top > .return_link,
.centered-top-container.sticky .centered-top > .hamburger-menu,
.centered-top-container.sticky .centered-top > .return_link {
  order: 1 !important;
  position: static !important;
  float: none !important;
  flex: 0 0 36px !important;
  width: 36px !important;
  height: 36px !important;
  margin: 0 0 0 -6px !important;
  padding: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  box-sizing: border-box !important;
  cursor: pointer !important;
  z-index: 2 !important;
}
@media screen and (min-width: $(sidebar.width + content.width + content.margin * 2)) {
  .centered-top > .hamburger-menu,
  .centered-top-container.sticky .centered-top > .hamburger-menu {
    display: none !important;
  }
}

/* [Slot 2: Blog Title] Applies Identical 19px Pretendard Style to Both h1 (Home) and h1 a (Post) */
.centered-top > .blog-name,
body.item-view .centered-top > .blog-name,
.centered-top-container.sticky .centered-top > .blog-name,
body.collapsed-header .centered-top-container .blog-name {
  order: 2 !important;
  position: static !important;
  float: none !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  height: 36px !important;
  min-height: 36px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  text-align: left !important;
  opacity: 1 !important;
}
.blog-name #header,
.blog-name .Header,
.blog-name .header-widget,
.blog-name .header-widget > div,
body.item-view .blog-name #header,
body.item-view .blog-name .Header,
body.item-view .blog-name .header-widget,
body.item-view .blog-name .header-widget > div {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  height: 100% !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  min-width: 0 !important;
}
.Header h1,
body.item-view .Header h1,
.centered-top-container .Header h1,
.centered-top-container.sticky .Header h1,
body.collapsed-header .centered-top-container .widget.Header h1,
body.latex-font .Header h1 {
  color: var(--text-primary) !important;
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 19px !important;
  font-weight: 800 !important;
  line-height: 36px !important;
  letter-spacing: -0.03em !important;
  text-align: left !important;
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  height: 36px !important;
  display: block !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  min-width: 0 !important;
}
.Header h1 a,
body.item-view .Header h1 a,
.centered-top-container .Header h1 a,
.centered-top-container.sticky .Header h1 a,
body.latex-font .Header h1 a {
  color: var(--text-primary) !important;
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 19px !important;
  font-weight: 800 !important;
  line-height: 36px !important;
  letter-spacing: -0.03em !important;
  text-align: left !important;
  margin: 0 !important;
  padding: 0 !important;
  display: inline !important;
}

/* [Slot 3: Right Search Button] Always Locked to Right Axis */
.centered-top > .search,
body.item-view .centered-top > .search,
.centered-top-container.sticky .centered-top > .search {
  order: 3 !important;
  position: static !important;
  float: none !important;
  flex: 0 0 36px !important;
  width: 36px !important;
  height: 36px !important;
  margin: 0 -6px 0 auto !important;
  padding: 0 !important;
  border: none !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  z-index: 2 !important;
}

/* Inner Button & SVG Normalization for All 3 Header Icons */
.return_link button,
.return_link .flat-icon-button,
.search-expand,
.search-expand .flat-icon-button {
  width: 36px !important;
  height: 36px !important;
  margin: 0 !important;
  padding: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  line-height: 0 !important;
  box-sizing: border-box !important;
}
.hamburger-menu svg,
.return_link svg,
.search-expand svg {
  width: 22px !important;
  height: 22px !important;
  margin: 0 !important;
  padding: 0 !important;
  display: block !important;
}

#reading-progress-bar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px !important;
  background: var(--accent) !important;
  background-image: none !important;
  box-shadow: none !important;
  z-index: 999999;
  transform-origin: left;
  transform: scaleX(0);
  transition: transform .05s ease-out;
  will-change: transform;
}

/* --- 2.4 Primary Surfaces, Post Cards, Thumbnails & Notice Board --- */
.post-outer-container, .widget.FeaturedPost, .PopularPosts, #custom-notice-board {
  background: var(--bg-card) !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
  color: var(--text-body) !important;
  transform: none !important;
}
.centered-bottom,
body.item-view .centered-bottom,
body:not(.item-view) .centered-bottom {
  padding: 0 28px !important;
  box-sizing: border-box !important;
}
@media screen and (max-width: 800px) {
  .centered-bottom,
  body.item-view .centered-bottom,
  body:not(.item-view) .centered-bottom {
    padding: 0 20px !important;
  }
}
body.item-view .Blog .blog-posts .post-outer-container {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 16px 0 40px 0 !important;
}
body.item-view .post-title {
  border-bottom: none !important;
  padding: 0 !important;
  margin: 8px 0 10px 0 !important;
  float: none !important;
  max-width: 100% !important;
  font-size: 28px !important;
  line-height: 1.38 !important;
}
@media screen and (max-width: 800px) {
  body.item-view .post-title {
    font-size: 22px !important;
    line-height: 1.4 !important;
  }
}
body.item-view .post-header {
  border-bottom: 1px solid var(--border-subtle) !important;
  padding-bottom: 16px !important;
  margin-bottom: 28px !important;
}

/* Home 2-Column Bento Grid */
body:not(.item-view) .post-outer-container {
  position: relative !important;
  cursor: pointer !important;
  transition: transform .2s ease, border-color .2s ease, background-color .2s ease !important;
  border: none !important;
  background: var(--bg-surface-alt) !important;
  padding: 24px !important;
  margin-bottom: 16px !important;
  display: flex !important;
  flex-direction: column !important;
  box-shadow: none !important;
}
body:not(.item-view) .post-outer-container .post-outer {
  position: static !important;
  padding-bottom: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  flex: 1 1 auto !important;
}
body:not(.item-view) .post-outer-container .post-outer > .post {
  display: flex !important;
  flex-direction: column !important;
  flex: 1 1 auto !important;
}
body:not(.item-view) .post-outer-container .post-bottom {
  margin-top: auto !important;
  padding-top: 16px !important;
}
@media screen and (min-width: 960px) {
  body:not(.item-view) #Blog1 .blog-posts {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 20px !important;
    align-items: stretch !important;
  }
  body:not(.item-view) .post-outer-container {
    margin-bottom: 0 !important;
  }
}
@media (hover: hover) and (pointer: fine) {
  body:not(.item-view) .post-outer-container:hover {
    background: var(--bg-card-hover) !important;
  }
  body:not(.item-view) .post-outer-container:hover .post-title,
  body:not(.item-view) .post-outer-container:hover .post-title a {
    color: var(--accent) !important;
  }
}
body:not(.item-view) .post-title {
  float: none !important;
  max-width: 100% !important;
  font-size: 19px !important;
  line-height: 1.4 !important;
  margin-bottom: 8px !important;
}
.byline.post-timestamp, .notice-badge, .notice-date {
  font-family: Pretendard, sans-serif !important;
  font-size: 0.85em !important;
}
body:not(.item-view) .post-title a:after {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  z-index: 10;
}
body:not(.item-view) .byline, body:not(.item-view) .post-bottom, body:not(.item-view) .post-labels {
  position: relative;
  z-index: 11 !important;
}
body:not(.item-view) .post-header-line-1 {
  display: flex !important;
  flex-direction: row-reverse !important;
  align-items: center !important;
  justify-content: space-between !important;
  margin-bottom: 10px !important;
}
body:not(.item-view) .post-header-line-1 .post-share-buttons-top,
body:not(.item-view) .post-header-line-1 .byline.post-timestamp {
  float: none !important;
  margin: 0 !important;
}
.popular-posts-snippet .snippet-fade, .post-snippet .snippet-fade, .snippet-fade {
  background: none !important;
  display: inline-block !important;
  position: relative !important;
  width: auto !important;
  height: auto !important;
  color: inherit !important;
}
.snippet-fade:after {
  content: "..." !important;
  margin-left: 2px;
  background: none !important;
}
.snippet-thumbnail {
  flex: 0 0 120px !important;
  overflow: hidden !important;
}
.snippet-thumbnail, .snippet-thumbnail img {
  width: 120px !important;
  height: 120px !important;
  min-width: 120px !important;
  min-height: 120px !important;
  display: block !important;
}
.snippet-thumbnail img {
  max-width: 120px !important;
  max-height: 120px !important;
  object-fit: cover !important;
}
@media screen and (max-width: 800px) {
  .snippet-thumbnail {
    flex: 0 0 90px !important;
  }
  .snippet-thumbnail, .snippet-thumbnail img {
    width: 90px !important;
    height: 90px !important;
    min-width: 90px !important;
    min-height: 90px !important;
  }
  .snippet-thumbnail img {
    max-width: 90px !important;
    max-height: 90px !important;
  }
}
body:not(.item-view) .Blog .blog-posts .post-body .snippet-thumbnail {
  float: none !important;
  width: 100% !important;
  height: auto !important;
  aspect-ratio: 21 / 9 !important;
  max-height: 160px !important;
  flex: none !important;
  min-width: unset !important;
  min-height: unset !important;
  max-width: 100% !important;
  margin: 0 0 14px !important;
  overflow: hidden !important;
  position: relative !important;
}
body:not(.item-view) .Blog .blog-posts .post-body .snippet-thumbnail img {
  width: 100% !important;
  height: 100% !important;
  min-width: unset !important;
  min-height: unset !important;
  max-width: 100% !important;
  max-height: unset !important;
  object-fit: cover !important;
}
body:not(.item-view) .snippet-thumbnail .byline.post-labels {
  position: absolute !important;
  bottom: 10px !important;
  left: 10px !important;
  z-index: 5 !important;
  margin: 0 !important;
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 4px !important;
}
body:not(.item-view) .snippet-thumbnail .byline.post-labels a {
  background: var(--bg-card) !important;
  border: 1px solid var(--border-solid) !important;
  color: var(--text-primary) !important;
  font-size: 11px !important;
  padding: 3px 9px !important;
}

/* Custom Notice Board */
#custom-notice-board {
  margin: 0 0 16px !important;
  border-left: 4px solid var(--accent) !important;
  overflow: hidden !important;
}
.notice-list {
  list-style: none !important;
  margin: 0 !important;
  padding: 0 !important;
}
.notice-list li {
  border-bottom: 1px solid var(--border-subtle) !important;
  margin: 0 !important;
}
.notice-list li:last-child {
  border-bottom: 0 !important;
}
.notice-list a {
  display: flex;
  align-items: center;
  padding: 16px 20px;
  text-decoration: none !important;
  transition: background-color .2s, color .2s !important;
}
@media (hover: hover) and (pointer: fine) {
  .notice-list a:hover {
    background-color: var(--accent-tint) !important;
    transform: none !important;
  }
  .notice-list a:hover .notice-title {
    color: var(--accent) !important;
    transform: none !important;
  }
  .notice-list a:hover .notice-date {
    color: var(--text-secondary) !important;
  }
}
.notice-badge, .notice-title {
  transition: all .2s ease !important;
}
.notice-badge {
  flex-shrink: 0;
  background: var(--accent) !important;
  color: var(--text-on-accent) !important;
  font-size: .75em;
  font-weight: 800;
  padding: 4px 8px;
  margin-right: 12px;
  box-shadow: none !important;
}
.notice-title {
  flex-grow: 1;
  color: var(--text-primary) !important;
  font-weight: 600;
  font-size: .95em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-right: 16px;
}
.notice-date {
  flex-shrink: 0;
  color: var(--text-muted) !important;
  font-size: .85em;
  font-weight: 500;
}

/* --- 2.5 Sidebar, Profile, Collapsible Gadgets & PopularPosts --- */
.sidebar-container, .sidebar_top_wrapper, .sidebar_top, .sidebar_bottom {
  background: var(--bg-card) !important;
  background-color: var(--bg-card) !important;
  background-image: none !important;
  box-shadow: none !important;
}
.sidebar-container {
  border-right: 1px solid var(--border-solid) !important;
  margin-top: 0 !important;
}
.sidebar_top_wrapper, .sidebar_top, .sidebar_bottom {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  height: auto !important;
  max-height: none !important;
}
@media screen and (min-width: 0px) {
  .sidebar-container {
    margin-top: 0 !important;
  }
  .sidebar-container .sidebar_top_wrapper {
    height: auto !important;
    max-height: none !important;
    margin-top: 0 !important;
    width: 100% !important;
  }
  .sidebar-container .sidebar_top {
    height: auto !important;
    max-height: none !important;
    display: block !important;
    width: 100% !important;
  }
}

/* Sidebar Widgets & Dividers */
.sidebar-container .widget {
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
  transform: none !important;
  padding: 16px 0 !important;
  margin: 0 20px !important;
}
.sidebar-container .widget + .widget {
  border-top: 1px solid var(--border-subtle) !important;
}
.sidebar-container .widget .title {
  color: var(--text-primary) !important;
  font-weight: 700 !important;
}
.sidebar-container .widget:not(.Label) a:not(:hover),
.sidebar-container .widget li:not(.Label li) {
  color: var(--text-body) !important;
}
.sidebar-container .widget.Label a:not(:hover) {
  color: var(--label-text) !important;
}
.sidebar-container .widget a:hover {
  color: var(--accent) !important;
}

/* Sidebar Profile Widget (Centered Single Axis) */
.sidebar-container .widget.Profile {
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 auto !important;
  padding: 32px 20px 20px 20px !important;
  text-align: center !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  overflow: hidden !important;
}
.widget.Profile .individual {
  text-align: center !important;
  width: 100% !important;
}
.profile-img, .widget.Profile img,
.sidebar-container .widget.Profile .profile-img,
.sidebar-container .widget.Profile img {
  width: 100px !important;
  height: 100px !important;
  object-fit: cover !important;
  background: var(--bg-surface-alt) !important;
  padding: 5px !important;
  border: 1px solid var(--border-solid) !important;
  border-radius: 50% !important;
  margin: 0 auto 14px auto !important;
  display: block !important;
}
.sidebar-container .widget.Profile .profile-name,
.sidebar-container .widget.Profile .profile-link {
  text-align: center !important;
  margin-left: auto !important;
  margin-right: auto !important;
}
.widget.Profile h3.title {
  color: var(--text-primary) !important;
  font-size: 15px !important;
  font-weight: 700 !important;
  margin: 8px auto !important;
  text-align: center !important;
}
.widget.Profile .profile-textblock {
  color: var(--text-secondary) !important;
  font-size: 13px !important;
  line-height: 1.6 !important;
  margin: 8px auto !important;
  text-align: center !important;
}
.widget.Profile .profile-link.visit-profile {
  margin: 10px auto 0 auto !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 6px 18px !important;
  border: 1px solid var(--border-solid) !important;
  background: transparent !important;
  color: var(--accent) !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.5px !important;
  text-decoration: none !important;
  box-shadow: none !important;
  transition: all .15s ease !important;
  cursor: pointer !important;
}
@media (hover: hover) and (pointer: fine) {
  .widget.Profile .profile-link.visit-profile:hover {
    background: var(--accent) !important;
    border-color: var(--accent) !important;
    color: var(--text-on-accent) !important;
  }
}

/* Sidebar Collapsible Widgets */
.collapsible summary {
  list-style: none !important;
  cursor: pointer !important;
  outline: none !important;
  padding: 0 !important;
}
.collapsible summary::-webkit-details-marker {
  display: none !important;
}
.collapsible-title {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  width: 100% !important;
  box-sizing: border-box !important;
  cursor: pointer !important;
  padding: 0 4px !important;
}
.collapsible-title .title {
  flex: 1 1 auto !important;
  margin: 0 !important;
  font-size: 14px !important;
  font-weight: 700 !important;
  color: var(--text-primary) !important;
}
.collapsible-title .chevron-down,
.collapsible-title .chevron-up {
  color: var(--text-muted) !important;
  fill: var(--text-muted) !important;
  flex-shrink: 0 !important;
  width: 24px !important;
  height: 24px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
}
.collapsible-title .chevron-down svg,
.collapsible-title .chevron-up svg {
  fill: var(--text-muted) !important;
  color: var(--text-muted) !important;
  width: 20px !important;
  height: 20px !important;
}
details.collapsible[open] > summary .chevron-down,
details.collapsible:not([open]) > summary .chevron-up {
  display: none !important;
}
details.collapsible[open] > summary .chevron-up,
details.collapsible:not([open]) > summary .chevron-down {
  display: inline-flex !important;
}
@media (hover: hover) and (pointer: fine) {
  .collapsible summary:hover .title {
    color: var(--accent) !important;
  }
  .collapsible summary:hover .chevron-down,
  .collapsible summary:hover .chevron-up,
  .collapsible summary:hover .chevron-down svg,
  .collapsible summary:hover .chevron-up svg {
    color: var(--accent) !important;
    fill: var(--accent) !important;
  }
}

/* Followers Gadget */
.sidebar-container .widget.Followers {
  overflow: hidden !important;
}
.sidebar-container .widget.Followers iframe {
  max-width: 100% !important;
  border: none !important;
  filter: grayscale(1) opacity(0.85);
  transition: filter .2s ease;
}
.sidebar-container .widget.Followers:hover iframe {
  filter: none;
}

/* PopularPosts (post-of-the-week) - Compact 3-Column Grid & 2-Line Snippet */
#footer, .PopularPosts, .sidebar_bottom {
  content-visibility: auto;
  contain-intrinsic-size: 300px;
}
.PopularPosts {
  padding: 28px 0 !important;
  border-top: 1px solid var(--border-subtle) !important;
  margin-top: 40px !important;
}
.PopularPosts h2.title,
.PopularPosts h3.title {
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.05em !important;
  color: var(--text-muted) !important;
  margin: 0 0 14px 0 !important;
}
.PopularPosts div[role="feed"],
.PopularPosts ul {
  display: grid !important;
  grid-template-columns: 1fr !important;
  gap: 12px !important;
  list-style: none !important;
  padding: 0 !important;
  margin: 0 !important;
}
@media screen and (min-width: 900px) {
  .PopularPosts div[role="feed"],
  .PopularPosts ul {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
    gap: 16px !important;
  }
}
.PopularPosts .post {
  position: relative !important;
  cursor: pointer !important;
  border: none !important;
  background: var(--bg-surface-alt) !important;
  padding: 18px 20px !important;
  margin: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  transition: background-color .15s ease !important;
}
.PopularPosts .post + .post {
  border-top: none !important;
}
@media (hover: hover) and (pointer: fine) {
  .PopularPosts .post:hover {
    background-color: var(--bg-card-hover) !important;
  }
  .PopularPosts .post:hover .post-title a,
  .PopularPosts .post:hover .item-title a {
    color: var(--accent) !important;
  }
}
.PopularPosts .post-title,
.PopularPosts .item-title {
  float: none !important;
  max-width: 100% !important;
  margin: 0 0 4px 0 !important;
  font-size: 16px !important;
  line-height: 1.4 !important;
}
.PopularPosts .post-title a,
.PopularPosts .item-title a {
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  line-height: 1.4 !important;
  letter-spacing: -.02em !important;
  word-break: keep-all !important;
  display: -webkit-box !important;
  -webkit-line-clamp: 2 !important;
  -webkit-box-orient: vertical !important;
  overflow: hidden !important;
}
.PopularPosts .post-title a:not(:hover),
.PopularPosts .item-title a:not(:hover) {
  color: var(--text-primary) !important;
}
.PopularPosts .post-header .byline,
.PopularPosts .byline,
.PopularPosts .item-date {
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-style: normal !important;
  font-size: 12px !important;
  line-height: 1.4 !important;
  margin: 0 !important;
  color: var(--text-muted) !important;
}
.PopularPosts .item-content {
  color: var(--text-body) !important;
  margin-top: 8px !important;
  font-size: 13.5px !important;
  line-height: 1.55 !important;
}
.PopularPosts .popular-posts-snippet,
.PopularPosts .snippet-container,
.PopularPosts .snippet-item {
  display: -webkit-box !important;
  -webkit-line-clamp: 2 !important;
  -webkit-box-orient: vertical !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  max-height: 3.1em !important;
  line-height: 1.55 !important;
}
.PopularPosts .snippet-fade {
  display: none !important;
}
.PopularPosts .item-title a:after,
.PopularPosts .post-title a:after {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  z-index: 10;
}
.PopularPosts .item-thumbnail {
  display: none !important;
}

/* --- 2.6 Post Body, Typography, Section Folding, Links, Tables & Blockquotes --- */
.post-body {
  margin: 0 !important;
  padding: 4px 0 24px 0 !important;
  line-height: 1.65;
  font-size: 16px;
  color: var(--text-secondary) !important;
  word-break: break-word;
  overflow-wrap: break-word;
  counter-reset: h2-count h3-count h4-count h5-count math-callout !important;
}
.post-body p, .post-body li {
  color: var(--text-secondary) !important;
}
.post-title, .post-title a:not(:hover), .post-title a:visited:not(:hover),
.post-body h1, .post-body h2, .post-body h3, .post-body h4, .post-body h5 {
  color: var(--text-primary) !important;
}
.post-body h1, .post-body h2, .post-body h3, .post-title, .post-title a {
  font-weight: 800 !important;
  letter-spacing: -.5px !important;
}
.post-title a {
  transition: color .2s ease;
}
.post-title a:hover, body:not(.item-view) .post-title a:hover {
  color: var(--accent) !important;
  transition: color .2s ease !important;
}
.post-body h1, .post-body h2, .post-body h3, .post-body h4, .post-body h5 {
  line-height: 1.4;
  margin-top: 2.5em;
  margin-bottom: .8em;
}
.post-body h2, .post-body h3, .post-body h4, .post-body h5 {
  position: relative;
  padding-left: 20px !important;
  padding-top: 10px;
  padding-bottom: 10px;
  scroll-margin-top: 80px !important;
  border-bottom: none !important;
}
.post-body h2, .post-body h3, .post-body h4 {
  padding: 8px 12px 8px 22px !important;
  margin-top: 1.8em !important;
  margin-bottom: 0.4em !important;
  transition: background-color 0.15s ease !important;
}
@media (hover: hover) and (pointer: fine) {
  .post-body h2:hover, .post-body h3:hover, .post-body h4:hover {
    background-color: var(--bg-surface-alt) !important;
  }
}
@media (hover: none) {
  .post-body h2:active, .post-body h3:active, .post-body h4:active {
    background-color: var(--bg-surface-alt) !important;
  }
}
.post-body h2 *, .post-body h3 *, .post-body h4 *, .post-body h5 * {
  pointer-events: none !important;
}
.post-body h2 { font-size: 1.5em; }
.post-body h3 { font-size: 1.25em; }
.post-body h4 { font-size: 1em; font-weight: 700; }
.post-body h5 { font-size: .8em; font-weight: 700; }

/* Section Folding */
.section-toggle-icon {
  position: absolute;
  left: 4px;
  top: 50%;
  transform: translateY(-50%);
  font-size: .6em;
  color: var(--text-muted);
  transition: transform .3s cubic-bezier(.4, 0, .2, 1);
  cursor: pointer;
}
.heading-collapsed .section-toggle-icon {
  transform: translateY(-50%) rotate(-90deg);
  color: var(--text-secondary);
}
