  font-family: "Latin Modern Roman", "RIDIBatang", serif !important;
}
.callout[data-callout="증명"] .callout .callout-content:after,
.callout[data-callout="proof"] .callout .callout-content:after {
  content: none !important;
  display: none !important;
}
.callout[data-callout="증명"] .callout[data-callout="증명"] > .callout-content:after,
.callout[data-callout="proof"] .callout[data-callout="proof"] > .callout-content:after {
  content: "\220E" !important;
  display: block !important;
  float: none !important;
  text-align: right !important;
  margin-top: 4px !important;
  line-height: 1 !important;
  font-style: normal !important;
  font-family: Pretendard, sans-serif !important;
  font-size: 0.95em !important;
  color: var(--text-muted) !important;
}

/* Standard Obsidian Callout Types */
.callout[data-callout="info"], .callout[data-callout="note"], .callout[data-callout="todo"] { --c-color: var(--c-info); }
.callout[data-callout="abstract"], .callout[data-callout="hint"], .callout[data-callout="important"],
.callout[data-callout="summary"], .callout[data-callout="tip"], .callout[data-callout="tldr"] { --c-color: var(--c-tip); }
.callout[data-callout="check"], .callout[data-callout="done"], .callout[data-callout="success"] { --c-color: var(--c-success); }
.callout[data-callout="attention"], .callout[data-callout="caution"], .callout[data-callout="faq"],
.callout[data-callout="help"], .callout[data-callout="question"], .callout[data-callout="warning"] { --c-color: var(--c-warning); }
.callout[data-callout="bug"], .callout[data-callout="danger"], .callout[data-callout="error"],
.callout[data-callout="fail"], .callout[data-callout="failure"], .callout[data-callout="missing"] { --c-color: var(--c-danger); }
.callout[data-callout="cite"], .callout[data-callout="quote"] { --c-color: var(--c-quote); }

.callout:not([data-callout="theorem"]):not([data-callout="정리"]):not([data-callout="lemma"]):not([data-callout="보조정리"]):not([data-callout="proof"]):not([data-callout="증명"]):not([data-callout="definition"]):not([data-callout="정의"]):not([data-callout="corollary"]):not([data-callout="따름정리"]):not([data-callout="axiom"]):not([data-callout="공리"]):not([data-callout="example"]):not([data-callout="예시"]):not([data-callout="exercise"]):not([data-callout="연습"]):not([data-callout="연습문제"]) > .callout-title {
  background-color: transparent !important;
}
body .callout:not([data-callout="theorem"]):not([data-callout="정리"]):not([data-callout="lemma"]):not([data-callout="보조정리"]):not([data-callout="proof"]):not([data-callout="증명"]):not([data-callout="definition"]):not([data-callout="정의"]):not([data-callout="corollary"]):not([data-callout="따름정리"]):not([data-callout="axiom"]):not([data-callout="공리"]):not([data-callout="example"]):not([data-callout="예시"]):not([data-callout="exercise"]):not([data-callout="연습"]):not([data-callout="연습문제"]) > .callout-title > .callout-title-inner {
  color: rgb(var(--c-color, var(--c-quote))) !important;
}

/* --- 2.8 Code Blocks (Prism.js) & Inline Code --- */
.post-body pre {
  max-width: 100%;
  box-sizing: border-box;
}
div.code-toolbar {
  position: relative !important;
  margin: 2em 0 !important;
  overflow: hidden !important;
  background: var(--bg-code) !important;
  border: 1px solid var(--border-subtle) !important;
  box-shadow: none !important;
  padding-top: 44px !important;
}
div.code-toolbar > .toolbar {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 44px !important;
  background: var(--bg-surface-alt) !important;
  border-bottom: 1px solid var(--border-subtle) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  padding: 0 16px !important;
  box-sizing: border-box !important;
  opacity: 1 !important;
  visibility: visible !important;
}
div.code-toolbar > .toolbar .toolbar-item {
  display: inline-flex !important;
  align-items: center !important;
}
div.code-toolbar > .toolbar .toolbar-item:first-child {
  margin-right: auto !important;
}
div.code-toolbar > .toolbar .toolbar-item span {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: var(--text-tertiary) !important;
  font-family: "JetBrains Mono", Consolas, monospace !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
}
body div.code-toolbar code, body div.code-toolbar > pre,
code[class*="language-"], pre[class*="language-"] {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  margin: 0 !important;
  font-family: "JetBrains Mono", "SF Mono", Consolas, Monaco, monospace !important;
  font-size: .88em !important;
  line-height: 1.6 !important;
  color: var(--code-text) !important;
}
body div.code-toolbar > pre {
  padding: 16px 20px !important;
  overflow: auto !important;
}
div.code-toolbar > .toolbar .toolbar-item button {
  background: var(--bg-card) !important;
  color: var(--text-secondary) !important;
  border: 1px solid var(--border-subtle) !important;
  box-shadow: none !important;
  height: 30px !important;
  box-sizing: border-box !important;
  padding: 0 10px !important;
  font-size: 12px !important;
  line-height: 1 !important;
  min-width: 72px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  transform: none !important;
  transition: background-color .2s ease, color .2s ease, border-color .2s ease !important;
  margin-left: 4px !important;
  font-family: "Apple Color Emoji", "Segoe UI Emoji", sans-serif !important;
}
div.code-toolbar > .toolbar .toolbar-item button.latex-overleaf-btn {
  min-width: auto !important;
  border: none !important;
}
div.code-toolbar > .toolbar .toolbar-item button[data-copy-state="copy-success"] {
  background: var(--bg-surface-alt) !important;
  color: var(--callout-prob) !important;
  border-color: var(--callout-prob) !important;
}
@media (hover: hover) and (pointer: fine) {
  div.code-toolbar > .toolbar .toolbar-item button:not(.latex-overleaf-btn):hover {
    background: var(--accent) !important;
    color: var(--text-on-accent) !important;
    border-color: var(--accent) !important;
    transform: none !important;
  }
  div.code-toolbar > .toolbar .toolbar-item button.latex-overleaf-btn:hover {
    background: var(--overleaf-bg) !important;
    color: var(--text-on-accent) !important;
    transform: none !important;
  }
}
@media screen and (max-width: 600px) {
  div.code-toolbar > .toolbar .toolbar-item button {
    padding: 5px 8px !important;
    font-size: 11px !important;
    min-width: 64px !important;
  }
}
.callout-content code, .post-body code:not([class*="language-"]),
.post-body li code, .post-body p code {
  padding: 2px 6px !important;
  font-family: "JetBrains Mono", "SF Mono", Consolas, monospace !important;
  font-size: .9em !important;
  background-color: var(--bg-code-inline) !important;
  color: var(--text-primary) !important;
  border: none !important;
}
body .callout-content pre code, body .post-body pre code {
  background-color: transparent !important;
  border: none !important;
  padding: 0 !important;
  color: var(--code-text) !important;
}

/* Light Mode High-Contrast Syntax Highlighting (Overrides prism-tomorrow) */
body.light-mode code[class*="language-"],
body.light-mode pre[class*="language-"] {
  color: #181816 !important;
}
body.light-mode .token.comment,
body.light-mode .token.prolog,
body.light-mode .token.doctype,
body.light-mode .token.cdata {
  color: #5C5952 !important;
}
body.light-mode .token.punctuation {
  color: #3D3B36 !important;
}
body.light-mode .token.keyword,
body.light-mode .token.selector,
body.light-mode .token.important,
body.light-mode .token.atrule,
body.light-mode .token.builtin {
  color: #6D28D9 !important;
}
body.light-mode .token.function,
body.light-mode .token.class-name {
  color: #1E5080 !important;
}
body.light-mode .token.string,
body.light-mode .token.char,
body.light-mode .token.attr-value,
body.light-mode .token.regex,
body.light-mode .token.variable,
body.light-mode .token.inserted {
  color: #156F4B !important;
}
body.light-mode .token.number,
body.light-mode .token.boolean,
body.light-mode .token.constant,
body.light-mode .token.symbol,
body.light-mode .token.property,
body.light-mode .token.attr-name {
  color: #B45309 !important;
}
body.light-mode .token.operator,
body.light-mode .token.entity,
body.light-mode .token.url {
  color: #0F766E !important;
}
body.light-mode .token.tag,
body.light-mode .token.deleted {
  color: #B91C1C !important;
}

/* --- 2.9 Modern Series Navigation --- */
#modern-series-nav {
  background: var(--bg-surface-alt) !important;
  background-image: none !important;
  box-shadow: none !important;
  transform: none !important;
  margin: 48px 0 36px !important;
  border: 1px solid var(--border-subtle) !important;
  overflow: hidden !important;
}
#modern-series-nav:hover, .sidebar-container .widget:hover {
  transform: none !important;
  box-shadow: none !important;
}
.series-header {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  gap: 12px !important;
  padding: 15px 20px !important;
  cursor: pointer !important;
  background: transparent !important;
  border: none !important;
  transition: background-color .15s ease !important;
  margin-bottom: 0 !important;
  user-select: none !important;
}
.series-meta {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
}
.series-meta-right {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  flex-shrink: 0 !important;
}
.series-meta .badge {
  background: var(--accent-tint) !important;
  color: var(--accent) !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  letter-spacing: 0.04em !important;
  padding: 3px 7px !important;
  flex-shrink: 0 !important;
}
.series-title {
  color: var(--text-primary) !important;
  margin: 0 !important;
  font-weight: 700 !important;
  font-size: 15px !important;
  line-height: 1.4 !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
.series-count {
  color: var(--text-muted) !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  font-variant-numeric: tabular-nums !important;
}
.toggle-icon {
  color: var(--text-muted) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 18px !important;
  height: 18px !important;
  transition: transform .25s ease !important;
}
.series-header.open .toggle-icon {
  transform: rotate(180deg) !important;
}
.series-dropdown-list li {
  margin-bottom: 2px !important;
  line-height: 1.5 !important;
}
.series-dropdown-list li:last-child {
  margin-bottom: 0 !important;
}
.series-dropdown-list a {
  color: var(--text-secondary) !important;
  text-decoration: none !important;
  font-size: 14px !important;
  line-height: 1.45 !important;
  transition: background-color .15s ease, color .15s ease !important;
  display: block !important;
  width: 100% !important;
  padding: 7px 12px !important;
  box-sizing: border-box !important;
  cursor: pointer !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
.series-dropdown-list li.current a {
  color: var(--accent) !important;
  font-weight: 700 !important;
  background: var(--accent-tint) !important;
}
.series-dropdown-list li.current a:before {
  content: "\2713  ";
  font-weight: 800;
}
.series-dropdown {
  max-height: 350px !important;
  overflow-y: auto !important;
  background: transparent !important;
  border: none !important;
  border-top: 1px solid var(--border-subtle) !important;
  margin: 0 !important;
}
.series-dropdown-list {
  list-style: none !important;
  margin: 0 !important;
  padding: 12px 16px !important;
}
.series-nav-footer {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  border-top: 1px solid var(--border-subtle) !important;
  background: var(--bg-surface-alt) !important;
}
.nav-btn {
  padding: 14px 20px !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  min-width: 0 !important;
  width: 100% !important;
  box-sizing: border-box !important;
  text-decoration: none !important;
  transition: background-color .15s ease !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  transform: none !important;
}
.nav-btn.prev {
  text-align: left !important;
}
.series-nav-footer > :nth-child(2) {
  border-left: 1px solid var(--border-subtle) !important;
}
.nav-btn.next {
  text-align: right !important;
}
.nav-btn.empty {
  background: transparent !important;
  pointer-events: none !important;
}
.nav-btn .dir {
  font-size: 11.5px !important;
  color: var(--text-muted) !important;
  margin-bottom: 4px !important;
  font-weight: 600 !important;
  transition: color .15s ease !important;
}
.nav-btn .tit {
  font-size: 14px !important;
  color: var(--text-primary) !important;
  font-weight: 600 !important;
  line-height: 1.4 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  transition: color .15s ease !important;
}
@media (hover: hover) and (pointer: fine) {
  .nav-btn:not(.empty):hover {
    background: var(--bg-card-hover) !important;
    transform: none !important;
  }
  .nav-btn:not(.empty):hover .dir,
  .nav-btn:not(.empty):hover .tit {
    color: var(--accent) !important;
  }
  #modern-series-nav .series-header:hover {
    background: var(--bg-card-hover) !important;
    transform: none !important;
  }
  .series-dropdown-list a:hover {
    background: var(--bg-card-hover) !important;
    color: var(--accent) !important;
    text-decoration: none !important;
    transform: none !important;
  }
  .series-dropdown-list li.current a:hover {
    background: var(--accent-glow) !important;
    color: var(--accent) !important;
  }
}
@media screen and (max-width: 600px) {
  .series-nav-footer {
    grid-template-columns: 1fr !important;
  }
  .series-nav-footer > :nth-child(2) {
    border-left: none !important;
    border-top: 1px solid var(--border-subtle) !important;
  }
  .nav-btn.empty {
    display: none !important;
  }
  .nav-btn {
    padding: 13px 16px !important;
  }
}

/* --- 2.10 Floating ToC, Zen Mode, Settings Panel, Modals, Tooltips & Search --- */
#toc-wrapper, .page_body, .page_body .centered, .sidebar-container {
  transition: transform .4s cubic-bezier(.4, 0, .2, 1), opacity .4s cubic-bezier(.4, 0, .2, 1) !important;
}
#toc-wrapper, #toc-wrapper.folded, #settings-panel,
.floating-footnote-content, .reference-tooltip, .search-modal-content {
  background: var(--bg-card) !important;
  background-image: none !important;
  border: 1px solid var(--border-solid) !important;
  box-shadow: var(--shadow-elevated) !important;
  color: var(--text-secondary) !important;
}

/* Inline & Floating Table of Contents */
#toc-container {
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-solid);
  padding: 24px;
  margin: 1em 0 2.5em;
  box-shadow: none;
}
#toc-container .toc-title {
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 16px;
  font-size: 1.1em;
}
#toc-container ul { list-style: none; padding-left: 0; margin: 0; }
#toc-container ul ul { padding-left: 1.2em; margin-top: 8px; }
#toc-container li { margin-bottom: 10px; line-height: 1.4; }
#toc-container a { color: var(--text-secondary) !important; font-size: .95em; transition: color .2s ease; }
#toc-container a:hover { color: var(--accent) !important; }

#toc-wrapper {
  position: fixed;
  top: 80px;
  right: 30px;
  width: 300px;
  max-width: 85vw;
  max-height: 80vh;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  will-change: transform;
}
#toc-wrapper.dragging {
  transition: none !important;
}
#toc-wrapper.folded {
  width: 46px !important;
  height: 46px !important;
  overflow: hidden !important;
  top: auto !important;
  bottom: 30px !important;
  right: 30px !important;
  left: auto !important;
  transform: none !important;
}
.toc-header {
  padding: 12px 16px;
  cursor: grab;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-solid) !important;
  user-select: none;
  min-height: 50px;
  box-sizing: border-box;
}
.toc-header:active { cursor: grabbing; }
#toc-wrapper.folded .toc-header {
  border-bottom: none !important;
  padding: 0;
  justify-content: center;
  width: 100%;
  height: 100%;
}
#toc-wrapper.folded #settings-fab,
#toc-wrapper.folded .toc-reset-btn,
#toc-wrapper.folded .toc-title {
  display: none !important;
}
.toc-header-btns {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  height: 28px !important;
}
#toc-wrapper.folded .toc-header-btns {
  gap: 0 !important;
  width: 100% !important;
  height: 100% !important;
  justify-content: center !important;
}
.toc-title, #toc-wrapper .toc-title {
  font-weight: 700;
  color: var(--text-secondary) !important;
  font-size: 1.05em;
  pointer-events: none;
}
#settings-fab:not(.floating-settings-fab),
.toc-header-btns #settings-fab,
.toc-header-btns .toc-btn {
  position: static !important;
  width: 28px !important;
  height: 28px !important;
  padding: 0 !important;
  margin: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
  color: var(--text-secondary) !important;
  cursor: pointer !important;
  line-height: 1 !important;
  box-sizing: border-box !important;
  transition: color .2s, background-color .2s !important;
}
.toc-header-btns #settings-fab .gear-icon,
.toc-header-btns .toc-btn svg {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 14px !important;
  height: 14px !important;
  stroke-width: 2.5 !important;
  line-height: 0 !important;
}
#toc-wrapper.folded .toc-toggle-btn {
  color: var(--text-secondary);
  width: 100%;
  height: 100%;
  padding: 0;
  transition: color .2s;
  display: flex;
  justify-content: center;
  align-items: center;
}
#toc-wrapper.folded .toc-toggle-btn svg {
  width: 22px !important;
  height: 22px !important;
  stroke-width: 2 !important;
}

.toc-body {
  padding: 16px;
  overflow-y: auto;
  flex-grow: 1;
  max-height: calc(80vh - 50px);
}
#toc-wrapper.folded .toc-body { display: none; }
.toc-body ul { list-style: none; padding-left: 0; margin: 0; counter-reset: toc-item; }
.toc-body ul ul { padding-left: 1.2em; margin-top: 6px; }
.toc-body li { margin-bottom: 8px; line-height: 1.4; counter-increment: toc-item; }
.toc-body a, #toc-wrapper .toc-body a {
  color: var(--text-secondary) !important;
  font-size: .9em;
  transition: color .2s ease;
  text-decoration: none;
  display: block;
}
#toc-wrapper .toc-body a.active {
  color: var(--accent) !important;
  font-weight: 700 !important;
}
@media (hover: hover) and (pointer: fine) {
  #toc-wrapper .toc-body a:hover {
    color: var(--accent) !important;
    background: var(--accent-tint) !important;
  }
  #toc-wrapper.folded:hover .toc-toggle-btn {
    color: var(--text-primary) !important;
  }
  .collapsible summary:hover .title,
  .collapsible summary:hover .chevron-down,
  .collapsible summary:hover .chevron-up,
  .collapsible summary:hover .chevron-down svg,
  .collapsible summary:hover .chevron-up svg {
    color: var(--accent) !important;
    fill: var(--accent) !important;
  }
}
@media (hover: none) {
  #toc-wrapper .toc-body a:active {
    color: var(--accent) !important;
    background: var(--accent-tint) !important;
  }
}
.toc-body a:before {
  content: counters(toc-item, ".") ". ";
  color: var(--accent);
  margin-right: 6px;
  font-weight: 600;
}

/* Zen Mode */
body.zen-mode .sidebar-container {
  transform: translateX(-100%) !important;
  opacity: 0;
}
body.zen-mode #toc-wrapper,
body.zen-mode #toc-wrapper.folded {
  transform: translateX(120%) !important;
  opacity: 0 !important;
  display: none !important;
  pointer-events: none !important;
}
body.zen-mode .zen-toggle-btn {
  background: var(--accent);
  color: var(--text-on-accent);
}
@media screen and (min-width: 1200px) {
  body.zen-mode .page_body {
    margin-left: 0 !important;
  }
  body.zen-mode .page_body .centered {
    max-width: 1050px !important;
  }
}

/* Settings Panel & Floating FAB */
#settings-panel {
  position: fixed !important;
  top: 50% !important;
  left: 50% !important;
  right: auto !important;
  width: 280px;
  z-index: 10005 !important;
  opacity: 0;
  transform: translate(-50%, -50%) !important;
  pointer-events: none;
  transition: transform .3s cubic-bezier(.4, 0, .2, 1), opacity .3s !important;
  transform-origin: center !important;
}
#settings-panel.open {
  opacity: 1 !important;
  transform: translate(-50%, -50%) scale(1) !important;
  pointer-events: auto !important;
}
.settings-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-solid) !important;
  font-weight: 700;
  color: var(--text-primary) !important;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.settings-body {
  padding: 8px 20px 20px;
}
.setting-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 16px;
  color: var(--text-secondary) !important;
  font-size: 15px;
}
.setting-group {
  display: flex !important;
  background: var(--bg-surface-alt) !important;
  border: 1px solid var(--border-solid) !important;
  padding: 3px !important;
  gap: 2px !important;
}
.setting-item .setting-group button {
  flex: 1 !important;
  background: transparent !important;
  color: var(--text-body) !important;
  border: 0 !important;
  box-shadow: none !important;
  padding: 6px 0 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  outline: none !important;
  transition: background-color .15s ease, color .15s ease !important;
}
@media (hover: hover) and (pointer: fine) {
  .setting-item .setting-group button:not(.active):hover {
    background: var(--bg-card-hover) !important;
    color: var(--text-primary) !important;
  }
}
.setting-item .setting-group button:not(.active):active {
  background: var(--accent-tint) !important;
}
.setting-item .setting-group button.active,
.setting-item .setting-group button.active:hover {
  background: var(--accent) !important;
  color: var(--text-on-accent) !important;
  border: 0 !important;
  box-shadow: none !important;
  cursor: default !important;
}
#st-zen-btn {
  background: var(--bg-surface-alt) !important;
  color: var(--text-body) !important;
  border: 1px solid var(--border-solid) !important;
  padding: 6px 14px !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  box-shadow: none !important;
  transition: background-color .15s ease, color .15s ease, border-color .15s ease !important;
}
@media (hover: hover) and (pointer: fine) {
  #st-zen-btn:not(.active):hover {
    background: var(--bg-card-hover) !important;
    color: var(--text-primary) !important;
    border-color: var(--border-medium) !important;
  }
}
#st-zen-btn.active,
#st-zen-btn.active:hover {
  background: var(--accent) !important;
  color: var(--text-on-accent) !important;
  border-color: var(--accent) !important;
  box-shadow: none !important;
}
#settings-fab {
  transition: background-color .2s ease, color .2s ease;
}
#settings-fab .gear-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform .4s ease;
  will-change: transform;
  transform-origin: center center;
}
#settings-fab:hover .gear-icon {
  transform: none;
}
#settings-fab.floating-settings-fab {
  position: fixed !important;
  bottom: 30px !important;
  right: 30px !important;
  width: 46px !important;
  height: 46px !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  background: var(--bg-card) !important;
  border: 1px solid var(--border-solid) !important;
  color: var(--text-primary) !important;
  box-shadow: var(--shadow-elevated) !important;
  z-index: 9999 !important;
  cursor: pointer !important;
  box-sizing: border-box !important;
  transition: background-color .2s, color .2s, border-color .2s !important;
}
#settings-fab.floating-settings-fab .gear-icon,
#settings-fab.floating-settings-fab svg {
  width: 20px !important;
  height: 20px !important;
  stroke-width: 2 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
}
@media (hover: hover) and (pointer: fine) {
  #settings-fab.floating-settings-fab:hover {
    background: var(--bg-card-hover) !important;
    color: var(--accent) !important;
    border-color: var(--accent) !important;
  }
}
@media (hover: none) {
  #settings-fab.floating-settings-fab:active {
    background: var(--accent-tint) !important;
  }
}

/* Close & Icon Buttons */
#search-cancel-btn, .footnote-close-btn, .ref-close-btn,
.settings-close, .toc-btn {
  background: transparent !important;
  color: var(--text-body) !important;
  border: 0 !important;
  box-shadow: none !important;
  transform: none !important;
  cursor: pointer;
}
@media (hover: hover) and (pointer: fine) {
  #search-cancel-btn:hover, .footnote-close-btn:hover, .ref-close-btn:hover,
  .settings-close:hover, .toc-btn:hover,
  #settings-fab:hover, .toc-header-btns #settings-fab:hover, .toc-header-btns .toc-btn:hover {
    background: var(--bg-card-hover) !important;
    color: var(--accent) !important;
    transform: none !important;
  }
}

/* Modal Backdrops */
.search-modal-backdrop, .dim-overlay {
  background: var(--bg-overlay) !important;
}

/* Footnotes & Reference Tooltips */
@keyframes popIn {
  0% { opacity: 0; }
  to { opacity: 1; }
}
.floating-footnote-content, .reference-tooltip {
  position: absolute;
  background: var(--bg-card) !important;
  border: 1px solid var(--border-medium) !important;
  box-shadow: var(--shadow-elevated) !important;
  z-index: 10010 !important;
  overflow: hidden;
}
.floating-footnote-content {
  width: fit-content;
  min-width: 150px;
  max-width: calc(100vw - 30px);
  box-shadow: inset 3px 0 0 var(--accent), var(--shadow-elevated) !important;
  animation: popIn .2s cubic-bezier(.175, .885, .32, 1.275);
}
.reference-tooltip {
  padding: 0 !important;
  max-width: 420px;
  width: max-content;
  font-size: .95em;
  line-height: 1.6;
  opacity: 0;
  visibility: hidden;
  transition: opacity .2s, transform .2s, visibility .2s;
  pointer-events: auto;
}
.footnote-inner-scroll, .ref-inner-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}
.footnote-inner-scroll {
  max-height: 50vh;
  padding: 16px 36px 16px 16px;
  font-size: .9em;
  color: var(--text-secondary);
  line-height: 1.6;
}
.ref-inner-scroll {
  padding: 16px 40px 16px 20px !important;
}
.footnote-close-btn, .ref-close-btn {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  line-height: 1;
  z-index: 10011;
  transition: all .2s ease !important;
}
.ref-inner-scroll > p, .reference-tooltip > p {
  margin-top: 0 !important;
}
.floating-footnote-content, .floating-footnote-content *,
.footnote-tooltip, .footnote-tooltip *,
.reference-tooltip, .reference-tooltip *,
.reference-tooltip .callout, .reference-tooltip .callout-title,
.reference-tooltip .callout-title-inner, .reference-tooltip blockquote, .reference-tooltip p {
  font-style: normal !important;
}
.floating-footnote-content .mjx-i, .floating-footnote-content [class*="mjx-i"],
.footnote-tooltip .mjx-i, .footnote-tooltip [class*="mjx-i"],
.reference-tooltip .mjx-i, .reference-tooltip [class*="mjx-i"] {
  font-style: italic !important;
}
.floating-footnote-content mjx-container[display="true"],
.footnote-tooltip mjx-container[display="true"],
.reference-tooltip mjx-container[display="true"] {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
  box-sizing: border-box !important;
  padding: 8px 0 !important;
  margin: 1em auto !important;
  text-align: center !important;
}
.floating-footnote-content mjx-container:not([display="true"]),
.footnote-tooltip mjx-container:not([display="true"]),
.reference-tooltip mjx-container:not([display="true"]) {
  max-width: 100% !important;
}
.floating-footnote-content mjx-container svg,
.footnote-tooltip mjx-container svg,
.reference-tooltip mjx-container svg {
  max-width: 100% !important;
  height: auto !important;
}
.floating-footnote-content .callout-title-inner:before, .floating-footnote-content .callout-title:before,
.footnote-tooltip .callout-title-inner:before, .footnote-tooltip .callout-title:before,
.reference-tooltip .callout-title-inner:before, .reference-tooltip .callout-title:before {
  display: none !important;
  content: none !important;
}
.baked-num {
  display: block !important;
  font-size: 1.05em !important;
  font-weight: 700 !important;
  margin-bottom: 6px !important;
}
.reference-tooltip .callout .callout-title,
.reference-tooltip .callout .callout-title-inner {
  font-size: .95em !important;
  margin-bottom: 6px !important;
}
.floating-footnote-content .callout, .floating-footnote-content .callout-content, .floating-footnote-content .callout-title-inner,
.reference-tooltip .callout, .reference-tooltip .callout-content, .reference-tooltip .callout-title-inner,
blockquote .callout, blockquote .callout-content, blockquote .callout-title-inner {
  text-align: left !important;
  color: inherit !important;
}
@media (max-width: 768px) {
  .reference-tooltip {
    left: 15px !important;
    right: 15px !important;
    width: auto !important;
    max-width: none !important;
  }
  .ref-inner-scroll {
    padding: 14px 36px 14px 16px !important;
    font-size: .9em !important;
  }
}
.floating-footnote-content mark, .footnote-tooltip mark, .reference-tooltip mark {
  background-color: var(--highlight-bg) !important;
  color: var(--text-primary) !important;
  padding: 2px 6px !important;
  font-weight: 600 !important;
}
.floating-footnote-content b, .floating-footnote-content strong,
.footnote-tooltip b, .footnote-tooltip strong,
.reference-tooltip b, .reference-tooltip strong {
  color: var(--text-primary) !important;
  font-weight: 700 !important;
}
.floating-footnote-content b a, .floating-footnote-content strong a,
.footnote-tooltip b a, .footnote-tooltip strong a,
.reference-tooltip b a, .reference-tooltip strong a {
  color: var(--link-color) !important;
  font-weight: inherit;
}
.reference-tooltip a, .reference-tooltip sup a {
  color: var(--accent) !important;
}
a.ref-link {
  text-decoration: underline solid var(--accent) !important;
  text-underline-offset: 4px;
  color: var(--accent) !important;
  font-weight: 600;
  cursor: pointer;
  transform: none !important;
}
a[href*="#fn"]:not(.footnote-backref) {
  padding: 4px 6px !important;
  margin: -4px 2px !important;
  display: inline-block;
  position: relative;
  z-index: 5;
  text-decoration: none !important;
  color: var(--accent) !important;
  cursor: pointer !important;
  transform: none !important;
}
a[href*="#fn"]:not(.footnote-backref):hover,
a[href*="#fn"]:not(.footnote-backref):active {
  background: var(--accent-tint) !important;
  color: var(--accent) !important;
  transform: none !important;
}

/* Spotlight Search Modal */
#spotlight-search-modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  height: 100dvh;
  z-index: 99999;
  display: flex;
  justify-content: center;
  align-items: center;
  visibility: hidden;
  opacity: 0;
  transition: opacity .2s ease, visibility .2s;
}
#spotlight-search-modal.active {
  visibility: visible;
  opacity: 1;
}
.search-modal-backdrop {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
.search-modal-content {
  position: relative;
  width: 90%;
  max-width: 650px;
  max-height: 80vh;
  max-height: 80dvh;
  display: flex;
  flex-direction: column;
  transform: none;
  transition: transform .2s cubic-bezier(.175, .885, .32, 1.275);
  box-sizing: border-box !important;
}
.search-input-wrapper {
  display: flex;
  align-items: center;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-solid) !important;
  flex-shrink: 0;
  width: 100%;
  box-sizing: border-box !important;
}
.search-icon {
  font-size: 1.2em;
  margin-right: 12px;
  opacity: .7;
  flex-shrink: 0;
}
#spotlight-input {
  flex-grow: 1;
  background: var(--bg-input) !important;
  border: 1px solid var(--border-solid) !important;
  box-shadow: none !important;
  color: var(--text-primary) !important;
  font-size: 16px !important;
  outline: none;
  width: 100%;
  min-width: 0;
  box-sizing: border-box !important;
}
.tag-pill, .search-shortcut-hint {
  background: var(--bg-surface-alt) !important;
  color: var(--text-body) !important;
  border: 1px solid var(--border-solid) !important;
  font-size: .75em;
  font-weight: 600;
  padding: 4px 8px;
}
.search-results-wrapper {
  flex-grow: 1;
  overflow-y: auto;
  padding: 12px;
  min-height: 0;
}
#spotlight-results {
  list-style: none;
  margin: 0;
  padding: 0;
}
.result-item {
  display: flex;
  flex-direction: column;
  padding: 16px 20px !important;
  margin-bottom: 0 !important;
  border: 0 !important;
  border-bottom: 1px solid var(--border-subtle) !important;
  text-decoration: none !important;
  transition: background .1s;
}
.result-item.selected, .result-item:hover {
  background: var(--accent-tint) !important;
}
.result-title {
  font-size: 1.05em;
  font-weight: 700;
  color: var(--accent) !important;
  margin-bottom: 6px;
}
.result-summary {
  font-size: .85em;
  color: var(--text-body) !important;
  line-height: 1.5;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.result-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.search-hint {
  padding: 40px;
  text-align: center;
  color: var(--text-body);
  font-size: .95em;
}
.search-cancel-btn {
  display: none;
}
@media screen and (max-width: 768px) {
  #spotlight-search-modal {
    align-items: flex-start;
    padding-top: 16px;
  }
  .search-shortcut-hint {
    display: none;
  }
  .search-cancel-btn {
    display: block !important;
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-weight: 600;
    padding-left: 12px;
    font-size: 16px;
    cursor: pointer;
  }
  .search-modal-content {
    max-height: 75vh;
    max-height: 75dvh;
    width: 94%;
  }
}

/* --- 2.11 Buttons, Labels & Pagination --- */
.jump-link, .jump-link.flat-button, .jump-link.flat-button.ripple,
.PopularPosts .jump-link, .post-bottom .jump-link {
  display: none !important;
}
#blog-pager, .blog-pager {
  display: none !important;
}
body.item-view .custom-pager-wrapper .pager-btn.disabled {
  display: none !important;
}
body.item-view .custom-pager-wrapper:has(.pager-btn.disabled:first-child):has(.pager-btn.disabled:last-child) {
  display: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
}
.extendable .show-less:hover, .extendable .show-more:hover {
  background-color: var(--accent) !important;
  color: var(--text-on-accent) !important;
  border-color: var(--accent) !important;
}
.comment-link {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px;
  height: 28px !important;
  padding: 0 10px !important;
  margin-left: -10px !important;
  box-sizing: border-box !important;
  line-height: 1 !important;
  vertical-align: middle !important;
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  color: var(--accent) !important;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none !important;
  transition: all .2s ease;
  position: relative;
  transform: none !important;
}
.comment-link .touch-icon {
  fill: currentColor;
  margin: 0 !important;
  padding: 0 !important;
  width: 14px !important;
  height: 14px !important;
  display: block !important;
}
.comment-link .num_comments {
  vertical-align: middle;
  line-height: 1 !important;
  display: inline-block !important;
}
@media (hover: hover) and (pointer: fine) {
  .comment-link:hover {
    background: var(--accent) !important;
    border-color: var(--accent) !important;
    color: var(--text-on-accent) !important;
    box-shadow: none !important;
    transform: none !important;
  }
}
.pill-button a {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 100% !important;
  height: 100% !important;
  text-decoration: none !important;
  color: inherit !important;
}

/* Load More Button */
.load-more-wrapper {
  margin: 40px 0 80px;
  padding-top: 30px;
  border-top: none;
  clear: both;
}
.load-more-btn, .load-more-wrapper {
  display: flex;
  justify-content: center;
}
.load-more-btn {
  padding: 14px 36px;
  background: var(--bg-card) !important;
  background-image: none !important;
  border: 1px solid var(--accent) !important;
  color: var(--accent) !important;
  box-shadow: none !important;
  transform: none !important;
  font-size: .95em;
  font-weight: 700;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color .2s, color .2s, border-color .2s;
  align-items: center;
  gap: 12px;
  min-width: 180px;
}
.lm-spinner {
  width: 18px;
  height: 18px;
  border: 2px solid var(--border-solid);
  border-top-color: var(--accent);
  animation: lm-spin .8s linear infinite;
}
@keyframes lm-spin {
  to { transform: rotate(1turn); }
}
@media (hover: hover) and (pointer: fine) {
  .load-more-btn:hover {
    background: var(--accent) !important;
    border-color: var(--accent) !important;
    color: var(--text-on-accent) !important;
    box-shadow: none !important;
    transform: none !important;
  }
}

/* Labels & Tags */
.Label li, .Label span.label-size {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 4px 6px 4px 0 !important;
  display: inline-block !important;
  vertical-align: middle !important;
}
.Label li a, .Label span.label-size a, .Label a, .byline.post-labels a {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 4px 10px !important;
  margin: 0 !important;
  background: var(--label-bg) !important;
  background-image: none !important;
  border: 1px solid var(--border-solid) !important;
  box-shadow: none !important;
  color: var(--label-text) !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  letter-spacing: .02em !important;
  text-decoration: none !important;
  box-sizing: border-box !important;
  cursor: pointer !important;
  transform: none !important;
  transition: background-color .15s ease, border-color .15s ease, color .15s ease !important;
}
.Label .label-count {
  margin-left: 4px !important;
  font-size: 0.9em !important;
  opacity: 0.8 !important;
}
@media (hover: hover) and (pointer: fine) {
  .Label li a:hover, .Label li:hover a,
  .Label span.label-size a:hover, .Label span.label-size:hover a,
  .Label a:hover, .byline.post-labels a:hover,
  body .Label li a:hover, body .Label li:hover a,
  body .Label a:hover, body .byline.post-labels a:hover,
  .sidebar-container .widget.Label a:hover,
  .sidebar-container .widget.Label li:hover a,
  .sidebar-container .widget.Label li a:hover,
  .sidebar-container .widget.Label a:hover *,
  .sidebar-container .widget.Label li:hover a *,
  body:not(.item-view) .snippet-thumbnail .byline.post-labels a:hover {
    background: var(--accent) !important;
    border-color: var(--accent) !important;
    color: var(--text-on-accent) !important;
    text-decoration: none !important;
    box-shadow: none !important;
    transform: none !important;
  }
}

/* Touch Device Transient Feedback (:active) */
@media (hover: none) {
  .Label li a:active, .byline.post-labels a:active,
  .comment-link:active, #settings-fab:active, .toc-btn:active,
  .nav-btn:active, .load-more-btn:active,
  .widget.Profile .profile-link.visit-profile:active,
  div.code-toolbar > .toolbar .toolbar-item button:active {
    background: var(--accent-tint) !important;
    border-color: var(--accent) !important;
    color: var(--accent) !important;
  }
  div.code-toolbar > .toolbar .toolbar-item button[data-copy-state="copy-success"]:active {
    background: var(--bg-surface-alt) !important;
    color: var(--accent) !important;
  }
}

/* --- 2.12 Comments Section --- */
.item-control {
  display: inline-block !important;
}
.comment-delete img {
  filter: invert(.8) !important;
  opacity: .5;
  transition: opacity .2s ease;
  vertical-align: middle;
}
.comment-delete:hover img {
  opacity: 1;
}
#comments .comment-form h4#comment-post-message,
#comments h3.title {
  position: static !important;
  clip: auto !important;
  width: auto !important;
  height: auto !important;
  overflow: visible !important;
  margin-bottom: 15px;
  font-size: 1.1em;
  font-weight: 700;
  color: var(--text-primary) !important;
}
.blogger-iframe-colorize, .comment-form iframe {
  color-scheme: var(--iframe-scheme) !important;
  background-color: var(--iframe-bg) !important;
  color: var(--text-secondary) !important;
  border: 1px solid var(--border-subtle) !important;
  box-sizing: border-box !important;
  width: 100% !important;
  min-height: 90px;
  display: block;
  filter: var(--iframe-filter) !important;
}
#comments {
  background: var(--bg-card) !important;
  background-image: none !important;
  border: 0 !important;
  border-top: 1px solid var(--border-subtle) !important;
  box-shadow: none !important;
  padding: 24px !important;
  margin-top: 32px;
  content-visibility: visible;
}
.comments {
  margin-top: 40px;
  box-sizing: border-box;
  width: 100%;
  overflow-x: hidden;
}
.comments .comments-content {
  margin-bottom: 20px;
  width: 100%;
  box-sizing: border-box;
}
.comments .comment-thread {
  padding: 0;
  margin: 0;
  list-style: none;
  width: 100%;
  box-sizing: border-box;
}
.comments .comment-thread > li {
  position: relative;
  width: 100%;
  box-sizing: border-box;
}
.comments .avatar-image-container {
  position: absolute;
  left: 0;
  top: 20px;
  width: 44px;
  height: 44px;
  overflow: hidden;
  background: var(--bg-surface-alt);
}
.comments .avatar-image-container img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.comments .comment-block {
  padding: 20px 0;
  border-bottom: 1px solid var(--border-subtle) !important;
}
.comments .comment-block, .comments .comment-replies {
  margin-left: 55px;
  box-sizing: border-box;
  width: calc(100% - 55px);
}
.comments .comment-replies {
  margin-top: 10px;
}
.comments .comment-replies .comment-thread > li {
  margin-bottom: 10px;
  position: relative;
}
.comments .comment-replies .avatar-image-container {
  width: 34px;
  height: 34px;
  top: 15px;
  left: 0;
}
.comments .comment-replies .comment-block {
  margin-left: 45px;
  padding: 15px;
  background: var(--bg-surface-alt) !important;
  border: 1px solid var(--border-solid) !important;
  box-sizing: border-box;
  width: calc(100% - 45px);
}
.comments .comment-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}
.comments .comment-header .user,
.comments .comment-header .user a,
.comments h4#comment-post-message {
  font-weight: 700;
  color: var(--text-primary) !important;
  text-decoration: none;
  font-size: .95em;
  word-break: break-all;
}
.comments h4#comment-post-message {
  margin-bottom: 15px;
  font-size: 1.1em;
}
.comments .comment-header .datetime,
.comments .comment-header .datetime a {
  color: var(--text-muted) !important;
  font-size: .8em;
  text-decoration: none;
}
#comments .comment-content, .comments .comment-content {
  color: var(--text-secondary) !important;
  font-size: .95em;
  line-height: 1.6;
  margin-top: 4px;
  overflow-wrap: break-word;
  word-wrap: break-word;
  word-break: break-word;
  white-space: normal;
}
#comments .comment .comment-actions:not(.hidden),
.comments .comment-actions:not(.hidden) {
  position: static !important;
  bottom: auto !important;
  margin-top: 6px;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
}
.comments .comment-thread > li > .comment-actions:not(.hidden) {
  margin-left: 55px;
}
.comments .comment-replies .comment-thread > li > .comment-actions:not(.hidden) {
  margin-left: 45px;
}
#comments .comment .comment-actions a,
.comments .comment-actions a {
  color: var(--text-muted);
  font-size: .85em;
  font-weight: 600;
  text-decoration: none;
  transition: color .2s;
  padding: 8px 4px;
  margin: 0;
  display: block;
}
#comments .comment .comment-actions a:hover,
.comments .comment-actions a:hover {
  color: var(--accent);
}
.comment-form, .comments .comment-form {
  margin-top: 30px;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  box-sizing: border-box;
  width: 100%;
  overflow: visible;
}
.comment-form p, .comments .comment-form p, .comments .comment-form .callout {
  color: var(--text-secondary) !important;
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  padding: 0 !important;
  margin-bottom: 15px;
}
@media screen and (max-width: 800px) {
  .comments { margin-top: 24px; padding: 0 4px; }
  .comments .avatar-image-container { width: 36px; height: 36px; top: 16px; }
  .comments .comment-block { padding: 12px 0; }
  .comments .comment-block, .comments .comment-replies { margin-left: 48px; width: calc(100% - 48px); }
  .comments .comment-replies .avatar-image-container { width: 28px; height: 28px; }
  .comments .comment-replies .comment-block { margin-left: 38px; padding: 10px 12px; width: calc(100% - 38px); }
  .comments .comment-thread > li > .comment-actions:not(.hidden) { margin-left: 48px; }
  .comments .comment-replies .comment-thread > li > .comment-actions:not(.hidden) { margin-left: 38px; }
  .comments .comment-header { gap: 6px; }
  .comments .comment-header .user { font-size: .9em; }
  .comments .comment-content { font-size: .9em; line-height: 1.55; }
  #comments .comment .comment-actions:not(.hidden) { gap: 12px; margin-bottom: 12px; }
  #comments .comment .comment-actions a { padding: 6px 2px; font-size: .8em; }
}
@media screen and (max-width: 480px) {
  .comments .avatar-image-container { width: 32px; height: 32px; }
  .comments .comment-block, .comments .comment-replies { margin-left: 42px; width: calc(100% - 42px); }
  .comments .comment-replies .comment-block { margin-left: 34px; width: calc(100% - 34px); padding: 8px 10px; }
  .comments .comment-thread > li > .comment-actions:not(.hidden) { margin-left: 42px; }
  .comments .comment-replies .comment-thread > li > .comment-actions:not(.hidden) { margin-left: 34px; }
}

/* --- 2.13 Skeleton UI & Page Rendering Transitions --- */
@keyframes shimmer {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}
@keyframes popInElements {
  0% { opacity: 0; }
  to { opacity: 1; }
}
.skeleton-ui,
html.is-rendering #modern-series-nav,
html.is-rendering .sidebar-container .widget,
html.is-rendering .widget.FeaturedPost {
  position: relative !important;
  overflow: hidden !important;
  background-color: var(--bg-surface-alt) !important;
  background-image: none !important;
  color: transparent !important;
  border: none !important;
  pointer-events: none !important;
  animation: shimmer 1.4s ease-in-out infinite !important;
}
.skeleton-ui::after,
html.is-rendering #modern-series-nav::after,
html.is-rendering .sidebar-container .widget::after,
html.is-rendering .widget.FeaturedPost::after {
  display: none !important;
  content: none !important;
  background: none !important;
}
.skeleton-ui > *,
html.is-rendering #modern-series-nav > *,
html.is-rendering .sidebar-container .widget > *,
html.is-rendering .widget.FeaturedPost > * {
  visibility: hidden !important;
  opacity: 0 !important;
}
.math-block.skeleton-ui, blockquote.skeleton-ui, pre.skeleton-ui {
  min-height: 80px;
}
.post-skeleton-wrapper {
  padding: 10px;
  width: 100%;
  box-sizing: border-box;
  animation: popIn .3s ease;
}
.post-skeleton-wrapper .skel-title { height: 40px; width: 70%; margin: 20px 0 30px; }
.post-skeleton-wrapper .skel-line { height: 20px; width: 100%; margin-bottom: 14px; }
.post-skeleton-wrapper .skel-line.short { width: 50%; margin-bottom: 40px; }
.post-skeleton-wrapper .skel-box { height: 220px; width: 100%; margin-bottom: 30px; }
body.item-view .post-body.is-loading,
html.is-rendering body.item-view .post-body {
  visibility: hidden !important;
  opacity: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
  pointer-events: none !important;
}
body.is-loaded #modern-series-nav,
body.is-loaded .post-body,
body.is-loaded .sidebar-container .widget, body.is-loaded .widget.FeaturedPost {
  opacity: 0;
  animation: popInElements .5s cubic-bezier(.175, .885, .32, 1.275) forwards;
}
body.is-loaded .post-body { animation-delay: 0s; }
body.is-loaded .sidebar-container .widget { animation-delay: .1s; }

/* --- 2.14 Responsive Mobile Typography & Flat Scrollbars --- */
@media screen and (max-width: 800px) {
  * { -webkit-tap-highlight-color: transparent !important; }
  body, html { background-attachment: scroll !important; }
  .post-body {
    font-size: 15.5px !important;
    line-height: 1.7 !important;
    word-break: keep-all !important;
  }
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.post-body .MathJax_Display::-webkit-scrollbar,
.post-body .katex-display::-webkit-scrollbar,
.post-body pre::-webkit-scrollbar,
.footnote-inner-scroll::-webkit-scrollbar,
.ref-inner-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: var(--scrollbar-track) !important;
}
::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb) !important;
  background-image: none !important;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--accent) !important;
}

/* =========================================================
   Swiss Technical Blueprint Refinements (Step 3: Workspace Layout & Border Removal)
   - 2.10 Post Width & 3-Column Desktop Workspace (Docked TOC)
   - Floating ToC Header & Monospace Section Counter
   - Footnote/Reference Popup .baked-num Inline Synchronization
   - 2.11 Monospace Stamp Labels & Borderless Comment Link
========================================================= */

/* 1. Post Content Width (860px Optimal Academic Width) */
body.item-view .page_body .centered {
  max-width: 860px !important;
}

/* 2. Desktop 3-Column Workspace (Fixed Right Docked TOC at >= 1360px) */
@media screen and (min-width: 1360px) {
  body.item-view:not(.zen-mode):not(.toc-folded) .page_body {
    padding-right: 280px !important;
  }
  body.item-view:not(.zen-mode) #toc-wrapper:not(.folded) {
    position: fixed !important;
    top: 0 !important;
    right: 0 !important;
    width: 280px !important;
    height: 100vh !important;
    max-height: 100vh !important;
    background: var(--bg-body) !important;
    border: none !important;
    border-left: 1px solid var(--border-subtle) !important;
    box-shadow: none !important;
    transform: none !important;
  }
  body.item-view:not(.zen-mode) #toc-wrapper:not(.folded) .toc-header {
    background: transparent !important;
    border-bottom: 1px solid var(--border-subtle) !important;
    padding: 0 20px !important;
    height: 56px !important;
    min-height: 56px !important;
    box-sizing: border-box !important;
    display: flex !important;
    align-items: center !important;
    cursor: default !important;
  }
  body.item-view:not(.zen-mode) #toc-wrapper:not(.folded) .toc-reset-btn {
    display: none !important;
  }
  body.item-view:not(.zen-mode) #toc-wrapper:not(.folded) .toc-body {
    max-height: calc(100vh - 56px) !important;
    padding: 16px 20px !important;
  }
}

/* 3. Floating ToC Header & Monospace Section Counter */
#toc-wrapper .toc-header {
  background: var(--bg-card-hover) !important;
}
.toc-body a:before {
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
}

/* 4. Footnote & Reference Tooltip .baked-num Monospace Badge */
.baked-num {
  display: inline-block !important;
  margin-bottom: 0 !important;
  margin-right: 8px !important;
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 0.88em !important;
  font-weight: 700 !important;
}
body.latex-font .baked-num {
  font-family: "Latin Modern Roman", "RIDIBatang", serif !important;
}

/* 5. Borderless Surface Stamp Labels */
.Label li a, .Label span.label-size a, .Label a, .byline.post-labels a {
  border: none !important;
  background: var(--bg-surface-alt) !important;
  padding: 4px 9px !important;
  font-family: Pretendard, -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 11.5px !important;
}

