body.script:
//
document.addEventListener("DOMContentLoaded", function() {

const postBody = document.body.classList.contains('item-view') ? document.querySelector('.post-body') : null;
if (postBody) {
  const headings = postBody.querySelectorAll('h2, h3, h4, h5');

    if (headings.length > 0) {

      // 🚀 [안드로이드 버그 완벽 차단] CSS에 의존하지 않고 JS로 본문에 직접 번호 하드코딩
      let hCounts = { 2: 0, 3: 0, 4: 0, 5: 0 };
      headings.forEach(heading => {
        if (heading.querySelector('.js-heading-num')) return; // 중복 방지
        const lvl = parseInt(heading.tagName.substring(1));
        hCounts[lvl]++;
        for (let i = lvl + 1; i <= 5; i++) hCounts[i] = 0;

        let numStr = hCounts[2];
        if (lvl === 2) numStr += ".";
        if (lvl >= 3) numStr += "." + hCounts[3];
        if (lvl >= 4) numStr += "." + hCounts[4];
        if (lvl >= 5) numStr += "." + hCounts[5];
        numStr += " ";

        const numSpan = document.createElement('span');
        numSpan.className = 'js-heading-num';
        numSpan.textContent = numStr;
        numSpan.style.color = 'var(--accent)';
        numSpan.style.marginRight = '6px';
        numSpan.style.pointerEvents = 'none';

        heading.insertBefore(numSpan, heading.firstChild);
      });

      const wrapper = document.createElement('div');

      wrapper.id = 'toc-wrapper';
      const header = document.createElement('div');
      header.className = 'toc-header';
      header.innerHTML = `
      <span class="toc-title">목차</span>
      <div class="toc-header-btns">
        <button class="toc-btn toc-reset-btn" title="맨 위로 고정">${refreshIcon}</button>
        <button class="toc-btn toc-toggle-btn" title="접기/펴기">${foldIconOpen}</button>
      </div>
      `;
      const tocBody = document.createElement('div');
      tocBody.className = 'toc-body';

      const rootUl = document.createElement('ul');
      let uls = { 2: rootUl }; let currentLevel = 2;
      headings.forEach((heading, index) => {
        const level = parseInt(heading.tagName.substring(1));
        heading.id = heading.id || 'heading-' + index;
        const li = document.createElement('li');
        const a = document.createElement('a');
        a.href = '#' + heading.id;
        // 사용자가 직접 입력한 숫자(1. 어쩌고 등)는 살리고, 자동 생성된 숫자/아이콘만 쏙 빼서 가져오기
let clone = heading.cloneNode(true);
let autoNum = clone.querySelector('.js-heading-num');
let iconNode = clone.querySelector('.section-toggle-icon');
if (autoNum) autoNum.remove();
if (iconNode) iconNode.remove();
a.innerHTML = clone.innerHTML.trim(); // 👈 수식 뼈대(HTML)까지 안전하게 복사!

        // [완벽 수정판] 목차 항목 클릭 시 접힌 섹션 자동 펼치기 및 이동
        a.addEventListener('click', function(e) {
          e.preventDefault();
          const href = this.getAttribute('href');
          const targetId = decodeURIComponent(href.substring(1));
          const targetHeading = document.getElementById(targetId) || document.getElementById(href.substring(1));

          if (targetHeading) {
            targetHeading.classList.remove('heading-collapsed');

            let prevNode = targetHeading.previousElementSibling;
            let targetLevel = parseInt(targetHeading.tagName.substring(1));

            while (prevNode) {
              if (prevNode.tagName && /^H[1-6]$/i.test(prevNode.tagName)) {
                const prevLevel = parseInt(prevNode.tagName.substring(1));
                if (prevLevel < targetLevel) {
                  prevNode.classList.remove('heading-collapsed');
                  targetLevel = prevLevel;
                }
              }
              prevNode = prevNode.previousElementSibling;
            }

            if (typeof window.syncFolding === 'function') window.syncFolding();

            targetHeading.scrollIntoView({ behavior: 'smooth', block: 'start' });
            history.pushState(null, null, href);
          }
        });

        li.appendChild(a);
        if (level > currentLevel) {
          for (let i = currentLevel + 1; i <= level; i++) {
            const newUl = document.createElement('ul');
            const parentUl = uls[i - 1] || rootUl;
            let parentLi = parentUl.lastElementChild || document.createElement('li');
            if (!parentUl.lastElementChild) parentUl.appendChild(parentLi);
            parentLi.appendChild(newUl);
            uls[i] = newUl;
          }
        }
        let targetUl = uls[level] || rootUl;
        targetUl.appendChild(li);
        currentLevel = level;
        for (let i = level + 1; i <= 6; i++) uls[i] = null;
      });

      tocBody.appendChild(rootUl);
      wrapper.appendChild(header);
      wrapper.appendChild(tocBody);
      document.body.appendChild(wrapper);

      let xOffset = 0, yOffset = 0;
      let isDragging = false, currentX, currentY, initialX, initialY;

      const resetPos = () => {
        xOffset = 0; yOffset = 0;
        wrapper.style.transform = `translate3d(0, 0, 0)`;
      };

// 드래그가 끝날 때 클래스 제거
      const dragEnd = () => {
        isDragging = false;
        wrapper.classList.remove('dragging');
      };

      header.addEventListener("mousedown", dragStart);
      document.addEventListener("mouseup", dragEnd);
      document.addEventListener("mousemove", drag);
      header.addEventListener("touchstart", dragStart, {passive: true});
      document.addEventListener("touchend", dragEnd);
      document.addEventListener("touchmove", drag, {passive: false});

      function dragStart(e) {
        if (e.target.closest('.toc-btn')) return;

        // 🚀 핵심: 드래그 시작 시 CSS 강제 종료 클래스 추가
        wrapper.classList.add('dragging');

        initialX = (e.type === "touchstart" ? e.touches[0].clientX : e.clientX) - xOffset;
        initialY = (e.type === "touchstart" ? e.touches[0].clientY : e.clientY) - yOffset;
        if (!wrapper.classList.contains('folded')) isDragging = true;
      }

      function drag(e) {
        if (isDragging && !wrapper.classList.contains('folded')) {
          e.preventDefault();
          currentX = (e.type === "touchmove" ? e.touches[0].clientX : e.clientX) - initialX;
          currentY = (e.type === "touchmove" ? e.touches[0].clientY : e.clientY) - initialY;

          const maxX = 30;
          const minX = -(window.innerWidth - wrapper.offsetWidth - 30);
          const maxY = window.innerHeight - wrapper.offsetHeight - 80;
          const minY = -80;

          if (currentX > maxX) currentX = maxX;
          if (currentX < minX) currentX = minX;
          if (currentY > maxY) currentY = maxY;
          if (currentY < minY) currentY = minY;

          xOffset = currentX; yOffset = currentY;
          wrapper.style.transform = `translate3d(${currentX}px, ${currentY}px, 0)`;
        }
      }

      header.querySelector('.toc-toggle-btn').onclick = () => {
        wrapper.classList.toggle('folded');
        const isFolded = wrapper.classList.contains('folded');
        header.querySelector('.toc-toggle-btn').innerHTML = isFolded ? foldIconFolded : foldIconOpen;

        if (isFolded) {
          document.body.classList.add('toc-folded');
          wrapper.style.transform = '';
        } else {
          document.body.classList.remove('toc-folded');
          wrapper.style.transform = `translate3d(${xOffset}px, ${yOffset}px, 0)`;
        }
      };

      header.querySelector('.toc-reset-btn').onclick = resetPos;
    }
  }

// ==========================================
  // 3. 모바일 최적화 각주 (모달 팝업 및 중첩 각주 완벽 지원)
  // ==========================================
  document.addEventListener('click', function(e) {
    const targetEl = e.target.nodeType === 3 ? e.target.parentNode : e.target;
    // ^(시작) 대신 *(포함)으로 변경하여 절대경로 변환 버그 원천 차단
    const ref = targetEl.closest('a[href*="#fn"]');

    if (!ref) return;
    const hrefAttr = ref.getAttribute('href') || '';
    if (hrefAttr.includes('#fnref') || ref.classList.contains('footnote-backref')) return;

    e.preventDefault();
    e.stopPropagation();

    // 🚀 핵심 버그 해결: 기존 팝업을 삭제하기 '직전'에 클릭한 각주의 현재 좌표(위치)를 미리 기억해둠!
    const rect = ref.getBoundingClientRect();

    const existingPopup = document.querySelector('.floating-footnote-content');
    if (existingPopup) {
      // 이미 열려있는 팝업과 같은 각주를 누르면 닫기만 하고 종료
      if (existingPopup.dataset.refId === ref.hash) {
        existingPopup.remove();
        return;
      }
      existingPopup.remove(); // 기존 팝업 삭제
    }

 // 🚀 모바일(?m=1) 절대경로 해시 파싱 버그 완벽 해결
const hashVal = ref.hash ? ref.hash : ('#' + ref.getAttribute('href').split('#')[1]);
const targetId = hashVal.substring(1);
const targetLi = document.getElementById(targetId);

    if (targetLi) {
      const popup = document.createElement('div');
      popup.className = 'floating-footnote-content';
      popup.dataset.refId = ref.hash;

      const innerScroll = document.createElement('div');
      innerScroll.className = 'footnote-inner-scroll';
      innerScroll.innerHTML = targetLi.innerHTML;

// --- 📌 여기서부터 [각주 팝업 번호 고정 로직 (함수 기반 데이터 결합 오버홀)] ---
const oTitles = targetLi.querySelectorAll('.callout-title-inner');
const cTitles = innerScroll.querySelectorAll('.callout-title-inner');
const oArr = targetLi.classList.contains('callout-title-inner') ? [targetLi] : Array.from(oTitles);
const cArr = innerScroll.classList.contains('callout-title-inner') ? [innerScroll] : Array.from(cTitles);

// 원본 태그 데이터와 브라우저 카운팅 순번을 조합하여 깨지지 않는 순수 문자열을 반환하는 함수
function bakeCalloutNumber(origNode) {
    if (!origNode) return null;
    const callout = origNode.closest('.callout');
    if (!callout) return null;

    const type = callout.getAttribute('data-callout') || '';
    const prefix = callout.getAttribute('data-prefix') || '';

    // 블로그 본문 안에 실제 정의된 수학 콜아웃만 넘버링 타겟으로 매핑
    const typeMap = {
        'definition': '정의', '정의': '정의',
        'theorem': '정리', '정리': '정리',
        'lemma': '보조정리', '보조정리': '보조정리',
        'corollary': '따름정리', '따름정리': '따름정리',
        'axiom': '공리', '공리': '공리',
        'example': '예시', '예시': '예시',
        'exercise': '연습', '연습': '연습', '연습문제': '연습',
        'proof': '증명', '증명': '증명'
    };

    const korType = typeMap[type.toLowerCase()];
    if (!korType) return null; // 대상이 아니면 번호 생성 안 함
    if (korType === '증명') return '증명.';

    // 본문 전체 흐름 내에서 이 콜아웃이 몇 번째 타겟 콜아웃인지 직접 계산 (CSS counter와 100% 동기화)
    const allCountableCallouts = Array.from(document.querySelectorAll('.post-body .callout')).filter(el => {
        const t = (el.getAttribute('data-callout') || '').toLowerCase();
        return ['definition', '정의', 'theorem', '정리', 'lemma', '보조정리', 'corollary', '따름정리', 'axiom', '공리', 'example', '예시', 'exercise', '연습', '연습문제'].includes(t);
    });

    const currentIndex = allCountableCallouts.indexOf(callout);
    if (currentIndex === -1) return null;

    const counterValue = currentIndex + 1; // 1-based index
    return `${korType} ${prefix}${counterValue}.`;
}

oArr.forEach((orig, index) => {
    if (cArr[index]) {
        const finalNumberString = bakeCalloutNumber(orig);
        if (finalNumberString) {
            // 원본 콜아웃 스타일의 고유 컬러 데이터 추출
            const origColor = window.getComputedStyle(orig).color;

            if (!cArr[index].querySelector('.baked-num')) {
                const numSpan = document.createElement('span');
                numSpan.className = 'baked-num';
                numSpan.textContent = finalNumberString + ' ';
                numSpan.style.color = origColor;
                cArr[index].prepend(numSpan);
            }
        }
    }
});
// --- 여기까지 ---

      // 팝업 안의 돌아가기 링크 제거
      const backref = innerScroll.querySelector('a.footnote-backref, a[href^="#fnref"]');
      if (backref) backref.remove();

      const closeBtn = document.createElement('span');
      closeBtn.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>`;
      closeBtn.className = 'footnote-close-btn';
      closeBtn.onclick = () => popup.remove();

      popup.appendChild(closeBtn);
      popup.appendChild(innerScroll);
      document.body.appendChild(popup);

      const popupWidth = popup.offsetWidth;
      const popupHeight = popup.offsetHeight;

      // 미리 기억해둔 rect 좌표를 사용해 팝업 띄울 위치 계산
      let topPos = rect.bottom + window.scrollY + 10;
      let leftPos = rect.left + window.scrollX;

      // 화면 오른쪽 이탈 방지
      if (leftPos + popupWidth > window.innerWidth - 15) {
        leftPos = window.innerWidth - popupWidth - 15;
      }
      if (leftPos < 15) leftPos = 15;

      // 화면 아래쪽 이탈 방지 (위로 띄움)
      if (rect.bottom + popupHeight + 15 > window.innerHeight) {
        topPos = rect.top + window.scrollY - popupHeight - 10;
        if (topPos < window.scrollY + 10) topPos = window.scrollY + 10;
      }

      popup.style.top = topPos + 'px';
      popup.style.left = leftPos + 'px';

      // 팝업창 내부에 있는 수학 수식도 다시 렌더링 (MathJax 동기화)
      if (window.MathJax && MathJax.typesetPromise) {
        MathJax.typesetPromise([popup]);
      }
    }
  });

  // PC 클릭 및 모바일 터치 완벽 대응
  const closeFootnotePopup = function(e) {
// 🚀 링크 시작(^)이 아닌 포함(*)으로 변경하여 모바일 터치 오작동 차단
if (!e.target.closest('.floating-footnote-content') && !e.target.closest('a[href*="#fn"]')) {
      const existingPopup = document.querySelector('.floating-footnote-content');
      if (existingPopup) existingPopup.remove();
    }
  };

  document.addEventListener('click', closeFootnotePopup);
  document.addEventListener('touchstart', closeFootnotePopup, { passive: true });

  // ==========================================
  // 5. 글 섹션 초기 로딩 접기 & 클릭 제어 (강력한 동기화)
  // ==========================================
  if (postBody) {
    const toggleHeadings = postBody.querySelectorAll('h2, h3, h4');

    toggleHeadings.forEach(heading => {
      heading.style.cursor = 'pointer';
      const icon = document.createElement('span');
      icon.className = 'section-toggle-icon';
      icon.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>`;
      heading.appendChild(icon);
      heading.classList.add('heading-collapsed');
    });

    const syncFolding = () => {
      let skipLevel = 0;
      let node = postBody.firstElementChild;

      while(node) {
        if (node.id === 'toc-wrapper') { node = node.nextElementSibling; continue; }
        const tag = node.tagName;
        const isHeading = tag && /^H[1-6]$/i.test(tag);
        const level = isHeading ? parseInt(tag.substring(1)) : 7;

        if (isHeading) {
          if (skipLevel > 0 && level <= skipLevel) {
            skipLevel = 0;
          }
          if (skipLevel > 0) {
            node.classList.add('hidden-section-content');
          } else {
            node.classList.remove('hidden-section-content');
            if (node.classList.contains('heading-collapsed')) {
              skipLevel = level;
            }
          }
        } else {
          if (skipLevel > 0) {
            node.classList.add('hidden-section-content');
          } else {
            node.classList.remove('hidden-section-content');
          }
        }
        node = node.nextElementSibling;
      }
    };

    window.syncFolding = syncFolding;
    syncFolding();

    toggleHeadings.forEach(heading => {
      heading.addEventListener('click', function() {
        this.classList.toggle('heading-collapsed');
        syncFolding();
      });
    });
  }

// ==========================================
// [옵시디언 호환 + 제목 넘버링] 전역 콜아웃 변환 (성능 최적화 통합판)
// ==========================================

  const CALLOUT_TITLE_REGEX = /^(?:<p>)?\s*\[!([^\]]+)\]([+-]?)([\s\S]*?)(?:\n\s*\n|<br\s*\/?>|<\/?(?:p|div)>|$)/i;
  const NUMBERED_CALLOUT_TYPES = new Set([
    'definition', '정의', 'theorem', '정리', 'lemma', '보조정리',
    'corollary', '따름정리', 'axiom', '공리', 'example', '예시',
    'exercise', '연습', '연습문제', '증명', 'proof'
  ]);
  const SKIP_CALLOUT_TAGS = new Set(['PRE', 'CODE', 'SCRIPT', 'STYLE', 'TEXTAREA', 'SVG', 'MJX-CONTAINER', 'NOSCRIPT']);
  const CALLOUT_FOLD_ICON_HTML = '<span class="callout-fold-icon"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="6 9 12 15 18 9"/></svg></span>';
  const CALLOUT_ICONS = {
    note: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"></path><path d="m15 5 4 4"></path></svg>',
    abstract: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="8" height="4" x="8" y="2" rx="1" ry="1"></rect><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><path d="M12 11h4"></path><path d="M12 16h4"></path><path d="M8 11h.01"></path><path d="M8 16h.01"></path></svg>',
    info: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 16v-4"></path><path d="M12 8h.01"></path></svg>',
    todo: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg>',
    tip: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"></path></svg>',
    success: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"></path></svg>',
    question: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"></path><path d="M12 17h.01"></path></svg>',
    warning: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"></path><path d="M12 9v4"></path><path d="M12 17h.01"></path></svg>',
    failure: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"></path><path d="m6 6 12 12"></path></svg>',
    danger: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"></polygon></svg>',
    bug: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m8 2 1.88 1.88"></path><path d="M14.12 3.88 16 2"></path><path d="M9 7.13v-1a3.003 3.003 0 1 1 6 0v1"></path><path d="M12 20c-3.3 0-6-2.7-6-6v-3a4 4 0 0 1 4-4h4a4 4 0 0 1 4 4v3c0 3.3-2.7 6-6 6"></path><path d="M12 20v-9"></path><path d="M6.53 9C4.6 8.8 3 7.1 3 5"></path><path d="M6 13H2"></path><path d="M3 21c0-2.1 1.7-3.9 3.8-4"></path><path d="M20.97 5c0 2.1-1.6 3.8-3.5 4"></path><path d="M22 13h-4"></path><path d="M17.2 17c2.1.1 3.8 1.9 3.8 4"></path></svg>',
    example: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="8" x2="21" y1="6" y2="6"></line><line x1="8" x2="21" y1="12" y2="12"></line><line x1="8" x2="21" y1="18" y2="18"></line><line x1="3" x2="3.01" y1="6" y2="6"></line><line x1="3" x2="3.01" y1="12" y2="12"></line><line x1="3" x2="3.01" y1="18" y2="18"></line></svg>',
    quote: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z"></path><path d="M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z"></path></svg>'
  };
  const CALLOUT_ICON_ALIASES = {
    abstract: 'abstract', summary: 'abstract', tldr: 'abstract',
    info: 'info',
    todo: 'todo',
    tip: 'tip', hint: 'tip', important: 'tip',
    success: 'success', check: 'success', done: 'success',
    question: 'question', help: 'question', faq: 'question',
    warning: 'warning', caution: 'warning', attention: 'warning',
    failure: 'failure', fail: 'failure', missing: 'failure',
    danger: 'danger', error: 'danger',
    bug: 'bug',
    example: 'example',
    quote: 'quote', cite: 'quote'
  };

  function getPostBodies(container) {
    if (!container || container === document) {
      return Array.from(document.querySelectorAll('.post-body'));
    }
    if (container.classList && container.classList.contains('post-body')) {
      return [container];
    }
    return container.querySelectorAll ? Array.from(container.querySelectorAll('.post-body')) : [];
  }

  function resolvePostPrefix(postBody) {
    const candidates = [];
    const bodyH1 = postBody.querySelector('h1');
    if (bodyH1) candidates.push(bodyH1.textContent);
    const postContainer = postBody.closest('.post-outer-container, .post');
    const postTitle = postContainer ? postContainer.querySelector('.post-title') : null;
    if (postTitle) candidates.push(postTitle.textContent);
    candidates.push(document.title);

    for (let i = 0; i < candidates.length; i++) {
      const text = candidates[i];
      if (!text) continue;
      const titleMatch = text.match(/([0-9]+[-.][0-9]+(?:[-.][0-9]+)*)/);
      if (titleMatch) {
        return titleMatch[1].split(/[-.]/).map(n => parseInt(n, 10)).join('.') + '.';
      }
    }
    return '';
  }

  function startsWithCalloutMarker(el) {
    let node = el.firstChild;
    while (node && node.nodeType === 3 && !node.nodeValue.trim()) {
      node = node.nextSibling;
    }
    if (!node) return false;
    if (node.nodeType === 3) {
      return node.nodeValue.trimStart().startsWith('[!');
    }
    if (node.nodeType === 1 && node.tagName === 'P' && (!node.attributes || node.attributes.length === 0)) {
      let inner = node.firstChild;
      while (inner && inner.nodeType === 3 && !inner.nodeValue.trim()) {
        inner = inner.nextSibling;
      }
      return !!(inner && inner.nodeType === 3 && inner.nodeValue.trimStart().startsWith('[!'));
    }
    return false;
  }

  function transformCalloutElement(el, localPrefix) {
    const html = el.innerHTML.trim();
    const match = html.match(CALLOUT_TITLE_REGEX);
    if (!match) return null;

    const fullMatch = match[0];
    const rawType = match[1].trim();
    const type = rawType.toLowerCase();
    const collapseSign = match[2];
    let titleHtml = match[3].trim();

    const isNumbered = NUMBERED_CALLOUT_TYPES.has(type);
    const pureTitle = titleHtml.replace(/#[^\s]+/g, '').trim();
    const hashMatch = titleHtml.match(/#[^\s]+/);
    const hashTag = hashMatch ? ' ' + hashMatch[0] : '';

    if (!pureTitle || pureTitle.toLowerCase() === rawType.toLowerCase()) {
      titleHtml = isNumbered
        ? hashTag
        : rawType.charAt(0).toUpperCase() + rawType.slice(1) + hashTag;
    }

    if (titleHtml) {
      titleHtml = titleHtml
        .replace(/\$\$([\s\S]+?)\$\$/g, '$$$1$$')
        .replace(/\\\[([\s\S]+?)\\\]/g, '\\($1\\)')
        .replace(/display="block"/g, 'display="inline"')
        .replace(/display="true"/g, 'display="false"')
        .replace(/class="math display"/g, 'class="math inline"')
        .replace(/class="katex-display"/g, 'class="katex"')
        .replace(/style="[^"]*display:[^;]*block[^"]*"/gi, 'style="display:inline"');
    }

    let innerHTML = html.slice(fullMatch.length).trim();
    const trimmedMatch = fullMatch.trim();
    if (/^<p>/i.test(trimmedMatch) && !/<\/p>$/i.test(trimmedMatch)) {
      innerHTML = '<p>' + innerHTML;
    }
    innerHTML = innerHTML.replace(/^(<br\s*\/?>|\n)+/i, '').trim();

    el.classList.add('callout');
    el.setAttribute('data-callout', type);
    el.innerHTML = '';

    const titleDiv = document.createElement('div');
    titleDiv.className = 'callout-title';

    let foldIconHtml = '';
    if (collapseSign === '+' || collapseSign === '-') {
      el.classList.add('is-collapsible');
      if (collapseSign === '-') el.classList.add('is-collapsed');
      foldIconHtml = CALLOUT_FOLD_ICON_HTML;
      titleDiv.addEventListener('click', function(e) {
        if (e.target.closest('a')) return;
        el.classList.toggle('is-collapsed');
      });
    }

    const iconKey = CALLOUT_ICON_ALIASES[type] || 'note';
    const iconHtml = isNumbered ? '' : '<div class="callout-icon">' + CALLOUT_ICONS[iconKey] + '</div>';

    titleDiv.innerHTML = foldIconHtml + iconHtml + '<div class="callout-title-inner"' + (localPrefix ? ' data-prefix="' + localPrefix + '"' : '') + '>' + titleHtml + '</div>';

    const contentDiv = document.createElement('div');
    contentDiv.className = 'callout-content';
    contentDiv.innerHTML = innerHTML;

    el.appendChild(titleDiv);
    el.appendChild(contentDiv);
    return contentDiv;
  }

  function processCalloutContainer(root, isDirectPostBody, localPrefix) {
    let el = root.firstElementChild;
    while (el) {
      const next = el.nextElementSibling;
      const tag = el.tagName;

      if (SKIP_CALLOUT_TAGS.has(tag)) {
        el = next;
        continue;
      }

      if (el.classList.contains('callout')) {
        const existingContent = el.querySelector(':scope > .callout-content');
        if (existingContent) processCalloutContainer(existingContent, false, localPrefix);
        el = next;
        continue;
      }

      const isCandidate = tag === 'BLOCKQUOTE' || tag === 'DIV' || (isDirectPostBody && tag === 'P');
      if (isCandidate && !el.classList.contains('not-callout') && startsWithCalloutMarker(el)) {
        const contentDiv = transformCalloutElement(el, localPrefix);
        if (contentDiv) {
          processCalloutContainer(contentDiv, false, localPrefix);
          el = next;
          continue;
        }
      }

      if (el.firstElementChild) {
        processCalloutContainer(el, false, localPrefix);
      }
      el = next;
    }
  }

  window.initCallouts = function(container = document) {
    getPostBodies(container).forEach(postBody => {
      if (postBody.dataset.calloutsDone === 'true') return;
      const localPrefix = resolvePostPrefix(postBody);
      processCalloutContainer(postBody, true, localPrefix);
      postBody.dataset.calloutsDone = 'true';
    });
  };

// ==========================================
// 🚀 [옵시디언 호환] [[위키링크]] 파싱 & 스포트라이트 검색 연동
// ==========================================
window.parseWikilinks = function(container = document) {
  getPostBodies(container).forEach(body => {
    if (body.dataset.wikilinksDone === 'true') return;

    // 1. 이미 <a> 태그로 변환된 위키링크들 처리 (Pandoc 등)
    const existingLinks = body.querySelectorAll('a[href]:not(.obsidian-wikilink)');
    existingLinks.forEach(a => {
      const href = a.getAttribute('href');
      if (!href || href.startsWith('http') || href.startsWith('//') || href.startsWith('#') || href.startsWith('mailto:')) return;

      a.classList.add('obsidian-wikilink');

      let targetKeyword = href.replace(/\.[a-zA-Z0-9]+$/, '').replace(/^\//, '');
      try { targetKeyword = decodeURIComponent(targetKeyword); } catch(e) {}

      a.href = 'javascript:void(0);';
      // 💡 개별 리스너 대신 data 속성에 검색어 주입
      a.setAttribute('data-wiki-target', targetKeyword);
    });

    // 2. 텍스트로 남아있는 [[위키링크]] 파싱
    const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, null, false);
    const nodesToReplace = [];
    let node;

    while (node = walker.nextNode()) {
      const parentEl = node.parentElement;
      if (!parentEl || parentEl.closest('a, pre, code, script, style, mjx-container, .MathJax_SVG')) continue;
      if (node.nodeValue.includes('[[')) nodesToReplace.push(node);
    }

    nodesToReplace.forEach(txtNode => {
      const text = txtNode.nodeValue;
      const regex = /\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g;
      if (!regex.test(text)) return;

      const fragment = document.createDocumentFragment();
      let lastIndex = 0;
      regex.lastIndex = 0;

      let match;
      while ((match = regex.exec(text)) !== null) {
        if (match.index > lastIndex) fragment.appendChild(document.createTextNode(text.substring(lastIndex, match.index)));

        const target = match[1].trim();
        const alias = match[2] ? match[2].trim() : target;

        const a = document.createElement('a');
        a.className = 'obsidian-wikilink';
        a.href = 'javascript:void(0);';
        a.textContent = alias;
        // 💡 개별 리스너 대신 data 속성에 검색어 주입
        a.setAttribute('data-wiki-target', target);

        fragment.appendChild(a);
        lastIndex = regex.lastIndex;
      }
      if (lastIndex < text.length) fragment.appendChild(document.createTextNode(text.substring(lastIndex)));
      txtNode.parentNode.replaceChild(fragment, txtNode);
    });

    body.dataset.wikilinksDone = 'true';
  });

  // 🚀 3. 이벤트 위임(Event Delegation) 처리
  // 팝업/모달로 복제되어 이벤트 리스너가 날아간 링크들도 클릭할 수 있도록 body 레벨에서 클릭을 감지함
  if (!document.body.dataset.wikiEventBound) {
    document.body.addEventListener('click', function(e) {
      const wikiLink = e.target.closest('a.obsidian-wikilink');
      if (wikiLink && wikiLink.hasAttribute('data-wiki-target')) {
        e.preventDefault();
        e.stopPropagation(); // 각주 팝업 등 다른 클릭 이벤트와 겹치지 않게 차단
        triggerSpotlightSearch(wikiLink.getAttribute('data-wiki-target'));
      }
    });
    // 이벤트가 중복 바인딩되지 않게 플래그 기록
    document.body.dataset.wikiEventBound = "true";
  }

  // 🚀 진짜 Ctrl+K 신호를 보내고 글자만 입력하는 함수
  function triggerSpotlightSearch(keyword) {
    const ctrlKEvent = new KeyboardEvent('keydown', {
      key: 'k',
      code: 'KeyK',
      keyCode: 75,
      which: 75,
      ctrlKey: true,
      metaKey: true,
      bubbles: true,
      cancelable: true
    });

    document.dispatchEvent(ctrlKEvent);

    setTimeout(() => {
      const searchInput = document.getElementById('spotlight-input');
      if (searchInput) {
        const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value").set;
        if (nativeInputValueSetter) {
          nativeInputValueSetter.call(searchInput, keyword);
        } else {
          searchInput.value = keyword;
        }

        searchInput.dispatchEvent(new Event('input', { bubbles: true }));
        searchInput.focus();
      }
    }, 100);
  }
};

// ==========================================
// 🚀 [옵시디언 호환] ==형광펜== 문법 자동 파싱
// ==========================================
window.parseObsidianHighlights = function(container = document) {
  getPostBodies(container).forEach(body => {
    if (body.dataset.highlightsDone === 'true') return;

    // 1. 본문 안의 모든 '텍스트 노드'만 안전하게 추출 (HTML 구조 보존)
    const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, null, false);
    const nodesToReplace = [];
    let node;

    while (node = walker.nextNode()) {
      const parentEl = node.parentElement;
      // 코드블록, 스크립트, 형광펜, 수식 내부는 무시
      if (!parentEl || parentEl.closest('mark, pre, code, script, style, mjx-container, .MathJax_SVG')) continue;

      // 텍스트에 '=='가 포함된 노드만 후보로 등록
      if (node.nodeValue.includes('==')) {
        nodesToReplace.push(node);
      }
    }

    nodesToReplace.forEach(txtNode => {
      const text = txtNode.nodeValue;

      // 🚀 [핵심 로직] 수식($...$)과 형광펜(==...==)을 동시 탐색하는 정규식
      const regex = /(\$\$[\s\S]+?\$\$|\$(?:\\.|[^$\\])+?\$)|==([\s\S]+?)==/g;

      if (!regex.test(text)) return;

      const fragment = document.createDocumentFragment();
      let lastIndex = 0;
      regex.lastIndex = 0; // test() 호출 후 인덱스 초기화

      let match;
      while ((match = regex.exec(text)) !== null) {
        // 매칭된 부분 이전의 일반 텍스트 보존
        if (match.index > lastIndex) {
          fragment.appendChild(document.createTextNode(text.substring(lastIndex, match.index)));
        }

        if (match[1]) {
          // ✅ 수식($a==b$)이 먼저 잡힌 경우: 형광펜으로 바꾸지 않고 '그대로' 텍스트로 보존 (보호 구역)
          fragment.appendChild(document.createTextNode(match[1]));
        } else if (match[2]) {
          // ✅ 형광펜(==텍스트==)이 잡힌 경우: <mark> 태그로 변환
          const mark = document.createElement('mark');
          mark.className = 'obsidian-highlight';
          mark.textContent = match[2];
          fragment.appendChild(mark);
        }
        lastIndex = regex.lastIndex;
      }

      // 남은 자투리 텍스트 마저 이어붙이기
      if (lastIndex < text.length) {
        fragment.appendChild(document.createTextNode(text.substring(lastIndex)));
      }

      // 기존 텍스트를 파싱된 조각들로 부드럽게 교체
      txtNode.parentNode.replaceChild(fragment, txtNode);
    });

    body.dataset.highlightsDone = 'true';
  });
};

window.initCodeBlocks = function(container = document) {
    const scope = (container && container !== document) ? container : document;

    // ① Pandoc 스타일(sourceCode) 변환 로직
    scope.querySelectorAll('pre.sourceCode').forEach(pre => {
      const code = pre.querySelector('code.sourceCode');
      if (code) {
        const langClass = Array.from(pre.classList).find(c => c !== 'sourceCode' && c !== 'numberSource');
        const lang = langClass ? 'language-' + langClass : 'language-none';
        const rawText = code.textContent;

        const newPre = document.createElement('pre');
        newPre.className = lang;
        const newCode = document.createElement('code');
        newCode.className = lang;
        newCode.textContent = rawText;
        newPre.appendChild(newCode);

        const parent = pre.parentElement;
        if (parent && parent.classList.contains('sourceCode') && parent.tagName === 'DIV') {
          parent.parentNode.replaceChild(newPre, parent);
        } else {
          pre.parentNode.replaceChild(newPre, pre);
        }
      }
    });

    // ② 수동 <pre><code> 태그 보정 (Prism 툴바 에러 방지) 및 1회만 하이라이팅
    getPostBodies(container).forEach(body => {
      if (body.dataset.codeDone === 'true') return;

      body.querySelectorAll('pre').forEach(pre => {
        if (!pre.className || !pre.className.includes('language-')) {
          pre.className = 'language-none';
        }
        const code = pre.querySelector('code');
        if (code && (!code.className || !code.className.includes('language-'))) {
          code.className = 'language-none';
        }
      });

      body.dataset.codeDone = 'true';
      if (window.Prism && typeof Prism.highlightAllUnder === 'function') {
        Prism.highlightAllUnder(body);
      }
    });

    if (container === document && window.Prism && typeof Prism.highlightAllUnder !== 'function') {
      Prism.highlightAll();
    }
  };

// ==========================================
  // 7. 🚀 Overleaf 연동 버튼을 "먼저" 등록 (Open in Overleaf)
  // ==========================================
  if (window.Prism && Prism.plugins.toolbar) {
    Prism.plugins.toolbar.registerButton('latex-overleaf', function(env) {
      if (env.language !== 'latex' && env.language !== 'tex') return null;

      const btn = document.createElement('button');
      btn.innerHTML = '<span style="color:#4CA746; margin-right:4px;">↗</span>Overleaf';
      btn.className = 'latex-overleaf-btn';

      btn.addEventListener('click', function() {
        let rawCode = env.element.textContent.trim();

        let compileCode = rawCode;
        if (!rawCode.includes('\\documentclass')) {
          compileCode = "\\documentclass{article}\n\\usepackage[utf8]{inputenc}\n\\usepackage{amsmath, amssymb,kotex}\n\\usepackage{tikz}\n\\usepackage{geometry}\n\\geometry{a4paper, margin=1in}\n\n\\begin{document}\n\n" + rawCode + "\n\n\\end{document}";
        }

        const form = document.createElement('form');
        form.method = 'POST';
        form.action = 'https://www.overleaf.com/docs';
        form.target = '_blank';

        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = 'snip';
        input.value = compileCode;

        form.appendChild(input);
        document.body.appendChild(form);
        form.submit();
        document.body.removeChild(form);
      });

      return btn;
    });
  }

  if (window.Prism && Prism.plugins.toolbar) {
    Prism.plugins.toolbar.registerButton('copy-to-clipboard', function(env) {
      const btn = document.createElement('button');
      btn.className = 'copy-code-btn';

      const clipboardIcon = `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="0" ry="0"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>`;
// #CED4DA 또는 #E5E8EB 중 마음에 드는 밝기로 선택하세요.
const checkIcon = `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>`;

      btn.innerHTML = clipboardIcon;

      btn.addEventListener('click', function(e) {
        const text = env.element.textContent;
        navigator.clipboard.writeText(text).then(function() {
          btn.innerHTML = checkIcon;
          btn.setAttribute('data-copy-state', 'copy-success');
          setTimeout(function() {
            btn.innerHTML = clipboardIcon;
            btn.removeAttribute('data-copy-state');
          }, 1800);
        });
        if (e && e.currentTarget) e.currentTarget.blur();
        btn.blur();
      });
      return btn;
    });

  }

// 본문 이미지 네이티브 지연 로딩 강제화 (스크롤 성능 향상)
  document.querySelectorAll('.post-body img').forEach(img => {
      if(!img.hasAttribute('loading')) img.setAttribute('loading', 'lazy');
  });

 });

