// 🚀 [글로벌] 스켈레톤 마스터 컨트롤러

window.SkeletonMaster = {
  apply: function(container) {
    // 1. 이미지는 로딩이 완전히 끝날 때까지 뼈대 유지 (댓글 영역 제외)
    const images = container.querySelectorAll('img');
    images.forEach(img => {
      if (img.closest('#comments')) return;
      if (!img.complete) {
        img.classList.add('skeleton-ui');
        if (!img.getAttribute('height')) img.style.minHeight = '200px';
        img.addEventListener('load', () => {
          img.classList.remove('skeleton-ui');
          img.style.minHeight = '';
        });
        img.addEventListener('error', () => img.classList.remove('skeleton-ui'));
      }
    });

    // ✨ 타겟이 글 목록(더보기 카드)일 때만 자기 자신도 뼈대 처리 (본문 post-body 삭제됨)
    if (container.classList && (container.classList.contains('post-outer-container') || container.classList.contains('post'))) {
      container.classList.add('skeleton-ui');
    }
  },

  remove: function(container) {
    // 내부 자식들의 뼈대 벗기기
    const blocks = container.querySelectorAll('.skeleton-ui:not(img)');
    blocks.forEach(b => b.classList.remove('skeleton-ui'));

    // ✨ 자기 자신이 뼈대였으면 본인도 벗기기
    if (container.classList && container.classList.contains('skeleton-ui')) {
      container.classList.remove('skeleton-ui');
    }
  }
};

// 쉬머링 코드
document.addEventListener("DOMContentLoaded", function() {

// 🚀 2. [클릭 반응 - 글 카드] 메인 화면 글 카드 클릭 시 전체 포커스
  if (!document.body.classList.contains('item-view')) {
    document.body.addEventListener('click', function(e) {
      const card = e.target.closest('.post-outer-container, .PopularPosts .post');
      if (!card) return;

      // 💡 [이슈 방어] 하단 '더보기(jump-link)' 버튼 내부나 테두리를 눌렀을 경우 실제 링크로 즉시 안내
      const jumpLink = e.target.closest('.jump-link');
      if (jumpLink) {
        const a = jumpLink.querySelector('a');
        if (a && e.target !== a) {
          a.click();
        }
        return;
      }

      // 💡 [이슈 방어] 태그, 날짜, 하단 버튼 등 개별 클릭이 필요한 요소를 눌렀을 때는 무시
      if (e.target.closest('.post-bottom, .post-labels, .byline')) return;

      // 💡 [이슈 방어] <a> 태그의 target="_blank" 이거나, Ctrl/Cmd/Shift/휠 클릭(새 창 열기)인 경우 작동 취소!
      if (e.target.tagName.toLowerCase() === 'a' && e.target.target === '_blank') return;
      if (e.ctrlKey || e.metaKey || e.shiftKey || e.button === 1) return;

      const mainLink = card.querySelector('.post-title a, .item-title a');
      if (!mainLink) return;

      // 원본은 놔두고 중복 클릭만 방지
      card.style.pointerEvents = 'none'; 

      // 나머지 카드들만 흐리게 처리
      document.querySelectorAll('.post-outer-container, .PopularPosts .post').forEach(other => {
        if (other !== card) {
          other.style.opacity = '0.4';
          other.style.pointerEvents = 'none';
        }
      });

      // 🚀 핵심 버그 픽스: <a> 태그를 정확히 누르지 않고 카드 여백을 눌렀더라도 강제로 페이지 이동!
      if (e.target.tagName.toLowerCase() !== 'a') {
        window.location.href = mainLink.href;
      }
    });
  }

  // 🚀 3. [클릭 반응 - 내부 링크] 사이드바 등 위젯 스켈레톤 변환
  const internalLinks = document.querySelectorAll('.sidebar-container a, .series-dropdown-list a, .nav-btn');
  internalLinks.forEach(link => {
    link.addEventListener('click', function(e) {
      // 💡 [이슈 방어] 새 창 열기 단축키 클릭 시 무시
      if (e.ctrlKey || e.metaKey || e.shiftKey || e.button === 1) return;

      const href = this.getAttribute('href');
      if (!href || href.startsWith('#') || this.target === '_blank') return;

      const parentWidget = this.closest('.widget, #modern-series-nav');
      if (parentWidget) {
        parentWidget.classList.add('skeleton-ui');
        parentWidget.style.pointerEvents = 'none';
      }
    });
  });

  // 🚀 [추가] 뒤로가기(Bfcache) 버그 완벽 복구 로직
  window.addEventListener('pageshow', function(e) {
    // 브라우저 뒤로가기/앞으로가기로 페이지에 진입했거나 캐시된 페이지일 때
    if (e.persisted || (window.performance && window.performance.getEntriesByType("navigation")[0].type === 'back_forward')) {

      // 1. 글 카드 흐림 효과 및 클릭 방지 모두 해제 (초기화)
      document.querySelectorAll('.post-outer-container, .PopularPosts .post').forEach(card => {
        card.style.opacity = '';
        card.style.pointerEvents = '';
      });

      // 2. 사이드바 등 위젯에 씌워졌던 스켈레톤 상태 강제 제거
      document.querySelectorAll('.skeleton-ui').forEach(el => {
        el.classList.remove('skeleton-ui');
        el.style.pointerEvents = '';
      });
    }
  });
  // 🚀 4. [글 본문 화면] 본문 가짜 스켈레톤 박스 생성
  const postBodyNode = document.querySelector('.post-body');
  let skelWrapper = null;

  if (postBodyNode && document.body.classList.contains('item-view')) {
    skelWrapper = document.createElement('div');
    skelWrapper.className = 'post-skeleton-wrapper';
    skelWrapper.innerHTML = `
      <div class="skeleton-ui skel-title"></div>
      <div class="skeleton-ui skel-line"></div>
      <div class="skeleton-ui skel-line"></div>
      <div class="skeleton-ui skel-line"></div>
      <div class="skeleton-ui skel-line short"></div>
      <div class="skeleton-ui skel-box"></div>
      <div class="skeleton-ui skel-line"></div>
      <div class="skeleton-ui skel-line short"></div>
    `;
    postBodyNode.parentNode.insertBefore(skelWrapper, postBodyNode);
  }

  // 🚀 5. [수식 렌더링 완료 후 봉인 해제!]
  SkeletonMaster.apply(document); 

  const collectScanText = (roots) => {
    const chunks = [];
    roots.forEach(root => {
      if (!root) return;
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
        acceptNode(node) {
          const tag = node.parentElement && node.parentElement.tagName;
          if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'NOSCRIPT') {
            return NodeFilter.FILTER_REJECT;
          }
          return NodeFilter.FILTER_ACCEPT;
        }
      });
      let current;
      while ((current = walker.nextNode())) {
        if (current.nodeValue) chunks.push(current.nodeValue);
      }
    });
    return chunks.join('\n');
  };

  const scanMathExtensions = () => {
    const matchedRoots = document.querySelectorAll('#main, .sidebar-container, #toc-wrapper');
    const roots = matchedRoots.length > 0 ? Array.from(matchedRoots) : (document.body ? [document.body] : []);
    if (roots.length === 0) return { hasMath: false, extraExts: [], text: '' };

    const text = collectScanText(roots);
    const hasScriptMath = !!document.querySelector('script[type^="math/tex"]');
    const hasMath = /\$|\\\(|\\\[/.test(text) || hasScriptMath;
    if (!hasMath) return { hasMath: false, extraExts: [], text };

    const extRules = [
      [/\\(?:color|textcolor|colorbox|fcolorbox)\b/, '[tex]/color'],
      [/\\boldsymbol\b/, '[tex]/boldsymbol'],
      [/\\(?:ce|pu)\s*\{/, '[tex]/mhchem'],
      [/\\(?:bra|ket|braket|set|Bra|Ket|Braket|Set)\b/, '[tex]/braket'],
      [/\\bbox\b/, '[tex]/bbox'],
      [/\\unicode\b/, '[tex]/unicode'],
      [/\\(?:xleftarrow|xrightarrow|xtwoheadleftarrow|xtwoheadrightarrow)\b/, '[tex]/extpfeil'],
      [/\\(?:dd|dv|pdv|fdv|qty|abs|norm|ev)\b/, '[tex]/physics']
    ];
    const extraExts = [];
    extRules.forEach(([regex, pkg]) => {
      if (regex.test(text)) extraExts.push(pkg);
    });
    return { hasMath: true, extraExts, text };
  };

  const waitForMathJaxReady = async () => {
    if (!window.MathJax) return null;
    if (!window.MathJax.typesetPromise) {
      const mjScript = document.getElementById('MathJax-script');
      if (mjScript) {
        await new Promise(resolve => {
          mjScript.addEventListener('load', resolve, { once: true });
          mjScript.addEventListener('error', resolve, { once: true });
          setTimeout(resolve, 10000);
        });
      }
    }
    if (window.MathJax.startup && window.MathJax.startup.promise) {
      await window.MathJax.startup.promise;
    }
    return window.MathJax;
  };

  const runPostRenderPipeline = (container = document) => {
    if (window.initCallouts) window.initCallouts(container);
    if (window.parseObsidianHighlights) window.parseObsidianHighlights(container);
    if (window.parseWikilinks) window.parseWikilinks(container);
    if (window.initCodeBlocks) window.initCodeBlocks(container);
    if (window.initCalloutAnchors) window.initCalloutAnchors(container);
  };

  const createFontLoadPromise = () => {
    if (!document.fonts || !document.fonts.load) return Promise.resolve();
    return Promise.all([
      document.fonts.load("400 16px 'RIDIBatang'", "가나다abc123ㄱㄴㄷ"),
      document.fonts.load("400 16px 'Latin Modern Roman'", "ABCabc123"),
      document.fonts.ready
    ]).catch(() => {});
  };

  const initRender = async () => {
    try {
      await new Promise(resolve => requestAnimationFrame(resolve));

      runPostRenderPipeline(document);

      const { hasMath, extraExts } = scanMathExtensions();

      const prepareMathJax = async () => {
        if (!hasMath) return;
        const mj = await waitForMathJaxReady();
        if (!mj) return;
        if (extraExts.length > 0 && mj.loader && typeof mj.loader.load === 'function') {
          try { await mj.loader.load(...extraExts); } catch(e) {}
        }
      };

      let fontsLoadedInTime = false;
      const fontPromise = createFontLoadPromise().then(() => { fontsLoadedInTime = true; });

      await Promise.all([
        prepareMathJax(),
        Promise.race([
          fontPromise,
          new Promise(resolve => setTimeout(resolve, 1500))
        ])
      ]);

      if (hasMath && window.MathJax && MathJax.typesetPromise) {
        try { await MathJax.typesetPromise(); } catch(e) {}
        if (!fontsLoadedInTime) {
          fontPromise.then(() => {
            if (window.MathJax && MathJax.typesetClear && MathJax.typesetPromise) {
              MathJax.typesetClear();
              MathJax.typesetPromise().catch(() => {});
            }
          });
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      if (typeof window.syncFolding === 'function') window.syncFolding();
      document.documentElement.classList.remove('is-rendering');
      document.body.classList.add('is-loaded');
      SkeletonMaster.remove(document);
      if (skelWrapper) skelWrapper.remove();
      if (postBodyNode) postBodyNode.style.display = '';
    }
  };

  initRender();

  // 아래부터는 기존 '더보기 + 복원' 로직
  if (document.body.classList.contains('item-view')) return;

  const blogWidget = document.querySelector('#Blog1');
  const blogPager1 = document.querySelector('.blog-pager');
  const blogPager2 = document.getElementById('blog-pager');
  const blogPager = blogPager1 ? blogPager1 : blogPager2;

  if (!blogWidget) return;
  if (blogPager) blogPager.style.display = 'none';

  const loadMoreWrapper = document.createElement('div');
  loadMoreWrapper.className = 'load-more-wrapper';
  loadMoreWrapper.innerHTML = '<button id="load-more-btn" class="load-more-btn">더보기 ↓</button>';
  blogWidget.parentNode.insertBefore(loadMoreWrapper, blogWidget.nextSibling);

  const loadMoreBtn = document.getElementById('load-more-btn');
  let nextPageUrl = '';

  const targetContainer1 = document.querySelector('#Blog1 .blog-posts');
  const targetContainer2 = document.querySelector('#Blog1 div[role="feed"]');
  const targetContainer3 = document.querySelector('#Blog1 .widget-content');
  const targetContainer = targetContainer1 ? targetContainer1 : (targetContainer2 ? targetContainer2 : targetContainer3);

  if (!targetContainer) return;

  const finalizeDynamicPosts = async (mathTargets) => {
    runPostRenderPipeline(targetContainer);
    if (window.initImageZoom) window.initImageZoom();
    if (window.MathJax && MathJax.typesetPromise) {
      try { await MathJax.typesetPromise(mathTargets); } catch(e){}
    }
    setTimeout(() => SkeletonMaster.remove(targetContainer), 300);
  };

  // 🚀 [핵심 수정 부분] 현재 접속한 URL 경로를 가져와서 고유한 캐시 키를 만듭니다.
  const currentPath = window.location.pathname + window.location.search;
  const cacheHtmlKey = 'blogger_saved_posts_' + currentPath;
  const cacheUrlKey = 'blogger_saved_next_url_' + currentPath;
  const cacheScrollKey = 'blogger_saved_scroll_' + currentPath;

  if (window.performance) {
    const navEntries = window.performance.getEntriesByType("navigation");
    if (navEntries.length > 0) {
      if (navEntries[0].type === "reload") {
        // 고정된 문자열 대신 동적 키(Key) 사용
        sessionStorage.removeItem(cacheHtmlKey);
        sessionStorage.removeItem(cacheUrlKey);
        sessionStorage.removeItem(cacheScrollKey);
      }
    }
  }

  // 고정된 문자열 대신 동적 키(Key) 사용
  const savedHtml = sessionStorage.getItem(cacheHtmlKey);
  const savedNextUrl = sessionStorage.getItem(cacheUrlKey);

  if (savedHtml) {
    targetContainer.insertAdjacentHTML('beforeend', savedHtml);

    // ✨ 복원된 데이터에도 렌더링 후 스켈레톤 벗기기 적용
    finalizeDynamicPosts([targetContainer]);

    // 고정된 문자열 대신 동적 키(Key) 사용
    const savedScroll = sessionStorage.getItem(cacheScrollKey);
    if (savedScroll) {
      setTimeout(function() { window.scrollTo(0, parseInt(savedScroll, 10)); }, 150);
    }
  }

  if (savedNextUrl) {
    nextPageUrl = savedNextUrl;
    if (nextPageUrl !== 'null') {
      loadMoreBtn.innerHTML = '더보기 ↓';
      loadMoreBtn.disabled = false;
    } else {
      loadMoreWrapper.style.display = 'none';
    }
  } else {
    updateNextPageUrl(document);
  }

  function updateNextPageUrl(doc) {
    const olderLink1 = doc.querySelector('#Blog1 .blog-pager-older-link');
    const olderLink2 = doc.querySelector('.blog-pager-older-link');
    const olderLink = olderLink1 ? olderLink1 : olderLink2;

    if (olderLink) {
      nextPageUrl = olderLink.href.split('#')[0];
    } else {
      nextPageUrl = 'null';
    }

    if (nextPageUrl === 'null') {
      loadMoreWrapper.style.display = 'none';
    } else {
      loadMoreBtn.innerHTML = '더보기 ↓';
      loadMoreBtn.disabled = false;
    }
    // 고정된 문자열 대신 동적 키(Key) 사용
    sessionStorage.setItem(cacheUrlKey, nextPageUrl);
  }

  loadMoreBtn.addEventListener('click', async function() {
    if (nextPageUrl === 'null') return;
    if (!nextPageUrl) return;

    loadMoreBtn.innerHTML = '<div class="lm-spinner"></div> 불러오는 중...';
    loadMoreBtn.disabled = true;

    try {
      const response = await fetch(nextPageUrl);
      const html = await response.text();
      const parser = new DOMParser();
      const doc = parser.parseFromString(html, 'text/html');
      const fetchedWidget = doc.querySelector('#Blog1');

      if (fetchedWidget) {
        const newPosts = fetchedWidget.querySelectorAll('.post-outer-container, article.post, .date-outer');

        if (newPosts.length > 0) {
          let rawHtmlToSave = '';

          newPosts.forEach(post => {
            post.style.animation = 'none';
            SkeletonMaster.apply(post); // ✨ 삽입 전에 미리 뼈대부터 입혀두기
            targetContainer.appendChild(post);
            rawHtmlToSave = rawHtmlToSave + post.outerHTML; 
          });

          // 고정된 문자열 대신 동적 키(Key) 사용
          const prevSaved = sessionStorage.getItem(cacheHtmlKey) || '';
          try {
            // 1. 평소처럼 누적 저장을 시도합니다.
            sessionStorage.setItem(cacheHtmlKey, prevSaved + rawHtmlToSave);
          } catch (error) {
console.warn('⚠️ 캐시 용량(5MB) 초과: 전체 더보기 캐시를 안전하게 비웁니다.');
  // blogger_saved_ 로 시작하는 모든 찌꺼기 캐시를 일괄 삭제
  Object.keys(sessionStorage).forEach(key => {
    if (key.startsWith('blogger_saved_')) {
      sessionStorage.removeItem(key);
    }
  });
}
        // ✨ 렌더링 완료 후 뼈대 벗기기 (CPU 최적화 적용)
          finalizeDynamicPosts(Array.from(newPosts));
        }
      }

      updateNextPageUrl(doc);

    } catch (error) {
      console.error("Load More Error:", error);
      loadMoreBtn.innerHTML = '불러오기 실패. 다시 시도';
      loadMoreBtn.disabled = false;
    }
  });

  window.addEventListener('beforeunload', function() {
    // 고정된 문자열 대신 동적 키(Key) 사용
    sessionStorage.setItem(cacheScrollKey, window.scrollY);
  });
});
//

  //
  // 플랫하고 직관적인 전역 SVG 아이콘 정의
  window.refreshIcon = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><path d="M23 4v6h-6"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>`;
  window.foldIconOpen = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><line x1="5" y1="12" x2="19" y2="12"/></svg>`;
  window.foldIconFolded = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>`;
  window.gearIcon = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>`;

document.addEventListener("DOMContentLoaded", function() {

const settingsWrapper = document.createElement('div');
settingsWrapper.innerHTML = `
<div id="settings-panel">
  <div class="settings-header">블로그 설정 <button class="settings-close" id="st-close-btn"><svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>
      <div class="settings-body">
        <div class="setting-item">
          <span style="white-space: nowrap; margin-right: 12px;">테마 모드</span>
          <div class="setting-group" id="theme-group" style="flex-grow: 1;">
            <button data-mode="light">라이트</button>
            <button data-mode="dark">다크</button>
            <button data-mode="auto">자동</button>
          </div>
        </div>
        <div class="setting-item">
          <span style="white-space: nowrap; margin-right: 12px;">폰트 스타일</span>
          <div class="setting-group" id="font-group" style="flex-grow: 1;">
            <button data-font="default">기본 (고딕)</button>
            <button data-font="latex">논문 (LaTeX)</button>
          </div>
        </div>
        <div class="setting-item" id="zen-option-item">
          <span>집중 모드 (Zen)</span>
          <button id="st-zen-btn">OFF</button>
        </div>
      </div>
    </div>
  `;

  document.body.appendChild(settingsWrapper);

// ⚙️ 2. 설정 버튼을 검색창에서 빼서 '플로팅 목차(ToC)' 안으로 쏙 이동!
const fab = document.createElement('button');
fab.id = "settings-fab";
fab.className = "toc-btn"; // 목차 버튼과 동일한 클래스 부여하여 완벽 동기화
fab.innerHTML = `<span class="gear-icon">${gearIcon}</span>`;
fab.title = "화면 설정";

  const tocHeaderBtns = document.querySelector('.toc-header-btns');
  if (tocHeaderBtns) {
    tocHeaderBtns.prepend(fab); // 새로고침(↺) 버튼 바로 왼쪽에 추가
  } else {
    // 혹시 목차가 없는 짧은 글일 경우를 대비해 우측 하단 플로팅으로 띄움
    document.body.appendChild(fab);
    fab.classList.add('floating-settings-fab');
  }

  // 팝업 열기/닫기 로직
  const panel = document.getElementById('settings-panel');
  fab.onclick = () => panel.classList.toggle('open');
  document.getElementById('st-close-btn').onclick = () => panel.classList.remove('open');

  // --- 3. 테마 로직 (자동 모드 포함) ---
  const themeBtns = document.querySelectorAll('#theme-group button');
  const applyTheme = (mode) => {
    document.body.classList.remove('light-mode');
    themeBtns.forEach(b => b.classList.remove('active'));
    document.querySelector(`[data-mode="${mode}"]`).classList.add('active');

if (mode === 'light') document.body.classList.add('light-mode');
    else if (mode === 'dark') { /* 기본이 다크 */ }
    else if (mode === 'auto') {
      if (window.matchMedia('(prefers-color-scheme: light)').matches) document.body.classList.add('light-mode');
    }
    localStorage.setItem('blog-theme-mode', mode);

    // 테마가 바뀌면 이미지 팝업 배경색도 즉시 새로운 테마에 맞게 변경!
    if (window.initImageZoom) window.initImageZoom();
  };

themeBtns.forEach(btn => {
    btn.onclick = () => applyTheme(btn.dataset.mode);
  });
  applyTheme(localStorage.getItem('blog-theme-mode') || 'auto');

// --- 폰트 변경 로직 ---
  const fontBtns = document.querySelectorAll('#font-group button');
  const applyFont = (font, isInitialLoad = false) => {
    document.body.classList.remove('latex-font');
    fontBtns.forEach(b => b.classList.remove('active'));

    const activeBtn = document.querySelector(`#font-group [data-font="${font}"]`);
    if (activeBtn) activeBtn.classList.add('active');

    if (font === 'latex') document.body.classList.add('latex-font');
    localStorage.setItem('blog-font-style', font);

    // 🔥 사용자가 버튼을 클릭해 폰트를 바꿀 때만 수식 재렌더링 (초기 로드 이중 렌더링 방지)
    if (!isInitialLoad && window.MathJax && MathJax.typesetClear) {
      setTimeout(() => {
        MathJax.typesetClear();
        MathJax.typesetPromise();
      }, 50);
    }
  };

  fontBtns.forEach(btn => {
    btn.onclick = () => applyFont(btn.dataset.font, false);
  });
  applyFont(localStorage.getItem('blog-font-style') || 'default', true);

// --- 4. 집중 모드 (데스크탑 전용) ---
  const zenBtn = document.getElementById('st-zen-btn');
  const zenOptionItem = document.getElementById('zen-option-item');

  // 모바일에서는 젠 모드 메뉴 숨김 (안전망 추가)
  if (window.innerWidth <= 800 && zenOptionItem) {
    zenOptionItem.style.display = 'none';
  }

  // 1. 페이지 로딩 시 브라우저에 저장된 젠 모드 상태 불러오기
  const isZenSaved = localStorage.getItem('blog-zen-mode') === 'on';
  if (isZenSaved) {
    zenBtn.textContent = "ON";
    zenBtn.classList.add('active');

    // 설정 버튼 미리 밖으로 빼놓기
    const fabBtn = document.getElementById('settings-fab');
    if (fabBtn) {
      document.body.appendChild(fabBtn);
      fabBtn.classList.add('floating-settings-fab');
    }
  }

  zenBtn.onclick = () => {
    document.body.classList.toggle('zen-mode');
    const isZen = document.body.classList.contains('zen-mode');

    // 2. 젠 모드 켜고 끌 때마다 브라우저에 상태 저장하기
    localStorage.setItem('blog-zen-mode', isZen ? 'on' : 'off');

    zenBtn.textContent = isZen ? "ON" : "OFF";
    zenBtn.classList.toggle('active', isZen);

    const fabBtn = document.getElementById('settings-fab');
    const tocHeaderBtns = document.querySelector('.toc-header-btns');

    // 💡 [안전망] 요소가 확실히 존재할 때만 스타일 조작
    if (fabBtn) {
      if (isZen) {
        document.body.appendChild(fabBtn);
        fabBtn.classList.add('floating-settings-fab');
      } else {
        if (tocHeaderBtns) {
          fabBtn.classList.remove('floating-settings-fab');
          tocHeaderBtns.prepend(fabBtn);
        }
        // 목차 헤더가 없다면(홈 화면 등) 아무 작업도 안 함 -> 플로팅 상태 유지! (완벽한 흐름)
      }
    }

    setTimeout(() => { if (typeof window.syncFolding === 'function') window.syncFolding(); }, 400);
  };
});
