window.initCalloutAnchors = function(container = document) {
  const scope = (container && container !== document) ? container : document;
  const usedIds = window.__usedCalloutIds = window.__usedCalloutIds || new Set();

  // 1. 콜아웃 중복 ID 방지 및 해시태그 파싱
  scope.querySelectorAll('.callout, .post-body blockquote').forEach((callout) => {
    if (callout.dataset.anchorDone === 'true') return;

    const titleEl = callout.querySelector('.callout-title-inner') || callout.querySelector('.callout-title') || callout.querySelector('p');
    if (!titleEl) return;

    if (callout.id) {
      usedIds.add(callout.id);
      callout.dataset.anchorDone = 'true';
      return;
    }

    let newId = '';
    const hashMatch = titleEl.textContent.match(/#([^\s]+)/);

    if (hashMatch) {
      newId = hashMatch[1];
      titleEl.innerHTML = titleEl.innerHTML.replace(hashMatch[0], '').trim();
    } else {
      newId = titleEl.textContent.trim().replace(/\s+/g, '').substring(0, 20);
    }

    if (!newId) newId = 'callout-box';

    let finalId = newId;
    let counter = 1;
    while (usedIds.has(finalId) || document.getElementById(finalId)) {
      finalId = newId + '-' + counter;
      counter++;
    }

    callout.id = finalId;
    usedIds.add(finalId);
    callout.dataset.anchorDone = 'true';
  });

  // 2. 참조 링크에 식별 클래스 추가 (새로운 위임 시스템용)
  const postBodies = (container && container.classList && container.classList.contains('post-body'))
    ? [container]
    : Array.from(scope.querySelectorAll('.post-body'));
  postBodies.forEach(body => {
    body.querySelectorAll('a[href^="#"]:not([href*="#fn"])').forEach(link => {
      link.classList.add('ref-link');
    });
  });
}; // initCalloutAnchors 종료

/* =========================================
   레퍼런스(참조) 전용 팝업 시스템 (각주 코드와 분리!)
   ========================================= */
(function() {
    let activeTooltip = null;

function removeActiveTooltip() {
    // 팝업이 존재하고, 누군가에 의해 강제 삭제되지 않고 화면에 남아있을 때만
    if (activeTooltip && document.body.contains(activeTooltip)) {
        activeTooltip.style.opacity = '0';
        activeTooltip.style.transform = 'translateY(10px)';
        const target = activeTooltip;
        setTimeout(() => { if(target && target.parentNode) target.remove(); }, 200);
    }
    // 변수는 무조건 즉시 초기화하여 유령 방지
    activeTooltip = null; 
}

    document.addEventListener('click', function(e) {
        // 🚀 각주 링크를 클릭한 거라면 이 스크립트는 즉시 정지 (살려두신 각주 코드가 작동하도록 양보)
        if (e.target.closest('a[href*="#fn"]')) return;

        // 각주가 아닌, 레퍼런스 링크(.ref-link, #ref)만 감지
        const refLink = e.target.closest('.ref-link, a[href*="#ref"]');
      if (refLink) {
            e.preventDefault();
            e.stopPropagation();

            removeActiveTooltip();

            let refHash = refLink.hash ? refLink.hash : ('#' + refLink.getAttribute('href').split('#')[1]);
            const targetId = decodeURIComponent(refHash.substring(1));
            let targetEl = document.getElementById(targetId) || document.querySelector(`[name="${targetId}"]`);

            if (targetEl && targetEl.closest('.callout')) {
                targetEl = targetEl.closest('.callout');
            } else if (targetEl && targetEl.closest('blockquote')) {
                targetEl = targetEl.closest('blockquote');
            }

            if (!targetEl) return;

            const tooltip = document.createElement('div');
            tooltip.className = 'reference-tooltip';

            // 🚀 X버튼을 고정시키기 위한 '내부 스크롤 래퍼' 추가
            const innerScroll = document.createElement('div');
            innerScroll.className = 'ref-inner-scroll';

            // 🚀 1. 이미 렌더링된 원본 콜아웃 요소를 깊은 복제(Deep Clone)
            const clone = targetEl.cloneNode(true);

            // 🚀 1.5. [번호 굽기] 원본의 가상 요소(::before) 텍스트를 실시간으로 가져와 복제본에 심어주기 (fallback 포함)
            const origTitles = targetEl.querySelectorAll('.callout-title-inner');
            const cloneTitles = clone.querySelectorAll('.callout-title-inner');

            const oArr = targetEl.classList.contains('callout-title-inner') ? [targetEl] : Array.from(origTitles);
            const cArr = clone.classList.contains('callout-title-inner') ? [clone] : Array.from(cloneTitles);

            oArr.forEach((orig, index) => {
                if (cArr[index]) {
                    const beforeStyle = window.getComputedStyle(orig, '::before');
                    let beforeContent = beforeStyle.content;
                    let finalNumberString = '';

                    // ① 실시간 렌더링된 가상 요소 텍스트 추출 시도
                    if (beforeContent && beforeContent !== 'none' && beforeContent !== 'normal') {
                        beforeContent = beforeContent.replace(/^['"]|['"]$/g, '').trim();
                        // attr이나 counter 키워드가 그대로 노출되는 원시 CSS 표현식이 아닐 때만 사용
                        if (beforeContent && !beforeContent.includes('attr(') && !beforeContent.includes('counter(')) {
                            finalNumberString = beforeContent;
                        }
                    }

                    // ② 추출 실패 시 (또는 브라우저가 원시 CSS 표현식을 반환했을 때) 안전한 JS Fallback 작동
                    if (!finalNumberString) {
                        const callout = orig.closest('.callout');
                        if (callout) {
                            const type = callout.getAttribute('data-callout') || '';
                            // data-prefix는 .callout-title-inner(orig) 요소에 저장되어 있으므로 orig에서 우선 탐색
                            const prefix = orig.getAttribute('data-prefix')
                                || callout.querySelector('.callout-title-inner')?.getAttribute('data-prefix')
                                || callout.getAttribute('data-prefix')
                                || '';
                            const typeMap = {
                                'definition': '정의', '정의': '정의',
                                'theorem': '정리', '정리': '정리',
                                'lemma': '보조정리', '보조정리': '보조정리',
                                'corollary': '따름정리', '따름정리': '따름정리',
                                'axiom': '공리', '공리': '공리',
                                'example': '예시', '예시': '예시',
                                'exercise': '연습', '연습': '연습', '연습문제': '연습',
                                'proof': '증명', '증명': '증명'
                            };
                            const korType = typeMap[type.toLowerCase()];
                            if (korType) {
                                if (korType === '증명') {
                                    finalNumberString = '증명.';
                                } else {
                                    const allCountableCallouts = Array.from(document.querySelectorAll('.post-body .callout')).filter(el => {
                                        const t = (el.getAttribute('data-callout') || '').toLowerCase();
                                        return ['definition', '정의', 'theorem', '정리', 'lemma', '보조정리', 'corollary', '따름정리', 'axiom', '공리', 'example', '예시', 'exercise', '연습', '연습문제'].includes(t);
                                    });
                                    const currentIndex = allCountableCallouts.indexOf(callout);
                                    if (currentIndex !== -1) {
                                        finalNumberString = `${korType} ${prefix}${currentIndex + 1}.`;
                                    }
                                }
                            }
                        }
                    }

                    // ③ 번호가 성공적으로 생성되었다면 주입
                    if (finalNumberString) {
                        const numSpan = document.createElement('span');
                        numSpan.className = 'baked-num';
                        numSpan.textContent = finalNumberString + ' ';

                        // 색상, 폰트 크기, 투명도 등 스타일 그대로 복사 (기본값 설정 포함)
                        numSpan.style.color = (beforeStyle && beforeStyle.color !== 'rgba(0, 0, 0, 0)') ? beforeStyle.color : '';
                        numSpan.style.fontSize = (beforeStyle && beforeStyle.fontSize) ? beforeStyle.fontSize : '0.85em';
                        numSpan.style.opacity = (beforeStyle && beforeStyle.opacity) ? beforeStyle.opacity : '0.9';

                        cArr[index].prepend(numSpan);
                    }
                }
            });

            // 🚀 2. ID 중복 방지를 위해 복제본 노드와 모든 하위 요소의 id 속성 완전히 제거
            clone.removeAttribute('id');
            clone.querySelectorAll('[id]:not(svg [id])').forEach(el => el.removeAttribute('id'));

            // 🚀 3. 팝업 내부에서 작동할 필요가 없는 각주 역링크(backref) 제거
            clone.querySelectorAll('a.footnote-backref').forEach(el => el.remove());

            // 🚀 4. 팝업 최상위(바깥쪽) 콜아웃만 무조건 펼치고(is-collapsed 제거), 내부에 중첩된(하위) 접이식 콜아웃들은 접었다 폈다 클릭할 수 있게 개별 대응
            if (clone.classList.contains('is-collapsible')) {
                clone.classList.remove('is-collapsed');
                const titleArea = clone.querySelector('.callout-title');
                if (titleArea) {
                    titleArea.style.cursor = 'default'; // 최상위 콜아웃은 팝업 내에서 더 이상 접히지 않으므로 기본 커서
                }
            }

            // 중첩된 하위 접이식 콜아웃들에 대해 접고 펴는 토글 클릭 이벤트 연결
            const nestedCollapsibleCallouts = clone.querySelectorAll('.callout.is-collapsible');
            nestedCollapsibleCallouts.forEach(nestedCallout => {
                // clone 자체가 .callout.is-collapsible일 경우 nestedCallout에 clone이 잡히므로 이는 최상위이므로 제외
                if (nestedCallout === clone) return;

                const titleArea = nestedCallout.querySelector('.callout-title');
                if (titleArea) {
                    titleArea.style.cursor = 'pointer'; // 클릭 가능하게 손가락 커서 적용
                    titleArea.addEventListener('click', function(ev) {
                        ev.preventDefault();
                        ev.stopPropagation(); // 클릭 시 부모 팝업 스크롤이나 닫기 이벤트 등으로 튀는 현상 방지
                        nestedCallout.classList.toggle('is-collapsed');
                    });
                }
            });

            // 🚀 5. 완전히 복제되고 정제된 콜아웃 요소를 스크롤 래퍼에 삽입
            innerScroll.appendChild(clone);

            // 🚀 X (닫기) 버튼 강제 주입
            const closeBtn = document.createElement('button');
            closeBtn.className = 'ref-close-btn';
            closeBtn.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>`;
            closeBtn.onclick = function(ev) {
                ev.preventDefault();
                ev.stopPropagation();
                removeActiveTooltip();
            };

            // 버튼과 스크롤 래퍼를 각각 본체에 삽입
            tooltip.appendChild(closeBtn);
            tooltip.appendChild(innerScroll);

            document.body.appendChild(tooltip);
            activeTooltip = tooltip;

            // 위치 및 스크롤 계산 로직
            const rect = refLink.getBoundingClientRect();
            const tooltipHeight = tooltip.scrollHeight;
            const tooltipWidth = tooltip.offsetWidth;
            const spaceBelow = window.innerHeight - rect.bottom;
            const spaceAbove = rect.top;

            let topPos, startTransform, maxHeight;

            if (tooltipHeight + 20 > spaceBelow && spaceAbove > spaceBelow) {
                maxHeight = spaceAbove - 20;
                topPos = rect.top + window.scrollY - Math.min(tooltipHeight, maxHeight) - 10;
                startTransform = 'translateY(-10px)';
            } else {
                maxHeight = spaceBelow - 20;
                topPos = rect.bottom + window.scrollY + 10;
                startTransform = 'translateY(10px)';
            }

            if (window.innerWidth > 768) {
                let leftPos = rect.left + window.scrollX;
                if (leftPos + tooltipWidth > window.innerWidth - 15) {
                    leftPos = window.innerWidth - tooltipWidth - 15;
                }
                if (leftPos < 15) leftPos = 15;
                tooltip.style.left = leftPos + 'px';
            }

            tooltip.style.setProperty('top', topPos + 'px', 'important');
            tooltip.style.setProperty('bottom', 'auto', 'important');
            tooltip.style.setProperty('position', 'absolute', 'important');
            tooltip.style.setProperty('visibility', 'visible', 'important');
            tooltip.style.setProperty('opacity', '1', 'important');
            tooltip.style.transform = 'translateY(0)';

            // 🚀 스크롤 속성을 툴팁 본체가 아니라 '내부 래퍼'에 부여! (X버튼 고정)
            innerScroll.style.setProperty('max-height', maxHeight + 'px', 'important');

            if (window.MathJax && window.MathJax.typesetPromise) {
                window.MathJax.typesetPromise([tooltip]);
            }
        }
        else if (activeTooltip && !e.target.closest('.reference-tooltip')) {
            removeActiveTooltip();
        }
    });
})();

/* =========================================================
   [팝업 통합 제어] 참조 팝업과 각주 팝업 상호 배제 (동시 실행 방지)
========================================================= */
document.addEventListener('click', function(e) {
    // 1. 참조 링크를 클릭했는지 감지
    const clickedRef = e.target.closest('a.ref-link');

    // 2. 각주 링크를 클릭했는지 감지 (다양한 각주 태그 형태 모두 호환)
    const clickedFootnote = e.target.closest('a.footnote-ref, a.footnote-backref, sup a, a[href^="#fn"]');

    if (clickedRef) {
        // 🚀 참조 링크를 눌렀다면 -> 기존에 열려있는 '각주 팝업'을 부드럽게 지움
        document.querySelectorAll('.floating-footnote-content, .footnote-tooltip, [class*="footnote-content"]').forEach(el => {
            el.style.opacity = '0'; 
            setTimeout(() => el.remove(), 200); // 0.2초 페이드아웃 애니메이션 후 DOM에서 완전히 삭제
        });
    }

    if (clickedFootnote) {
        // 🚀 각주 링크를 눌렀다면 -> 기존에 열려있는 '참조 팝업'을 부드럽게 지움
        document.querySelectorAll('.reference-tooltip').forEach(el => {
            el.style.opacity = '0';
            setTimeout(() => el.remove(), 200);
        });
    }
}, true); // 이벤트 캡처링(true)을 켜서 기존 팝업 스크립트들이 작동하기 '직전'에 선빵을 날려 청소합니다!

//
